class ARHSARowGatherLayerNormSm100:
    """Gather 128-wide rows and apply LayerNorm in one CTA per row."""

    arch = 100

    def __init__(self, *, num_threads: int = 128):
        self.num_threads = num_threads
        self.num_warps = num_threads // 32

    @cute.jit
    def __call__(
        self,
        mSrc: cute.Tensor,
        mRowIndex: cute.Tensor,
        mWeight: cute.Tensor,
        mBias: cute.Tensor,
        mOut: cute.Tensor,
        mXHat: cute.Tensor,
        mRstd: cute.Tensor,
        eps: Float32,
        total_rows: Int32,
        stream: cuda.CUstream,
    ):
        self.kernel(
            mSrc,
            mRowIndex,
            mWeight,
            mBias,
            mOut,
            mXHat,
            mRstd,
            eps,
        ).launch(
            grid=[total_rows, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mSrc: cute.Tensor,
        mRowIndex: cute.Tensor,
        mWeight: cute.Tensor,
        mBias: cute.Tensor,
        mOut: cute.Tensor,
        mXHat: cute.Tensor,
        mRstd: cute.Tensor,
        eps: Float32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        row_idx, _, _ = cute.arch.block_idx()
        src_row = Int32(mRowIndex[row_idx])
        lane = tidx % cute.arch.WARP_SIZE
        warp_idx = tidx // cute.arch.WARP_SIZE

        smem = cutlass.utils.SmemAllocator()
        sBuf = smem.allocate_tensor(
            Float32,
            cute.make_layout((4,)),
            byte_alignment=16,
        )

        x = Float32(mSrc[src_row, tidx])
        warp_sum = cute_utils.warp_reduce(x, lambda a, b: a + b)
        if lane == Int32(0):
            sBuf[warp_idx] = warp_sum
        cute.arch.barrier()

        row_sum = Float32.zero
        if warp_idx == Int32(0):
            if lane < Int32(self.num_warps):
                row_sum = sBuf[lane]
            row_sum = cute_utils.warp_reduce(row_sum, lambda a, b: a + b)
            if lane == Int32(0):
                sBuf[0] = row_sum
        cute.arch.barrier()

        mean = sBuf[0] * Float32(0.0078125)
        centered = x - mean
        sq = centered * centered
        warp_sq_sum = cute_utils.warp_reduce(sq, lambda a, b: a + b)
        if lane == Int32(0):
            sBuf[warp_idx] = warp_sq_sum
        cute.arch.barrier()

        row_sq_sum = Float32.zero
        if warp_idx == Int32(0):
            if lane < Int32(self.num_warps):
                row_sq_sum = sBuf[lane]
            row_sq_sum = cute_utils.warp_reduce(row_sq_sum, lambda a, b: a + b)
            if lane == Int32(0):
                sBuf[0] = row_sq_sum
        cute.arch.barrier()

        rstd = Float32(cute.math.rsqrt(sBuf[0] * Float32(0.0078125) + eps, fastmath=True))
        x_hat = centered * rstd
        mXHat[row_idx, tidx] = x_hat.to(mXHat.element_type)
        mOut[row_idx, tidx] = (
            x_hat * Float32(mWeight[tidx]) + Float32(mBias[tidx])
        ).to(mOut.element_type)
        if tidx == Int32(0):
            mRstd[row_idx, 0] = rstd.to(mRstd.element_type)


