class ARHSALeafGradAttnPackedTensorCoreD64Sm100:
    """Packed leaf-entry dO dot V pass using one 16x8x64 MMA tile per pack/head."""

    arch = 100

    def __init__(self, *, num_threads: int = 256):
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32

    @cute.jit
    def __call__(
        self,
        mLeafQueryIndex: cute.Tensor,
        mPackLeafEntryIndex: cute.Tensor,
        mPackValueIndex: cute.Tensor,
        mPackValueSlot: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.warps_per_cta)
        self.kernel(
            mLeafQueryIndex,
            mPackLeafEntryIndex,
            mPackValueIndex,
            mPackValueSlot,
            mValue,
            mGradReadout,
            mLeafGradAttn,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mLeafQueryIndex: cute.Tensor,
        mPackLeafEntryIndex: cute.Tensor,
        mPackValueIndex: cute.Tensor,
        mPackValueSlot: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        task_idx = block_idx * Int32(self.warps_per_cta) + warp_idx
        active = task_idx < total_tasks
        num_heads = Int32(mValue.shape[1])
        pack_idx = Int32(0)
        head_idx = Int32(0)
        if active:
            pack_idx = task_idx // num_heads
            head_idx = task_idx - pack_idx * num_heads

        smem = cutlass.utils.SmemAllocator()
        sDOAll = smem.allocate_tensor(
            mGradReadout.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mGradReadout.element_type, 64),
                (self.warps_per_cta * 16, 64),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sVAll = smem.allocate_tensor(
            mValue.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mValue.element_type, 64),
                (self.warps_per_cta * 8, 64),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sDO = cute.local_tile(sDOAll, (16, 64), (warp_idx, 0))
        sV = cute.local_tile(sVAll, (8, 64), (warp_idx, 0))

        for elem_idx in cutlass.range(lane, Int32(16) * Int32(64), cute.arch.WARP_SIZE, unroll=1):
            row_idx = elem_idx // Int32(64)
            dim_idx = elem_idx - row_idx * Int32(64)
            do_val = Float32(0.0).to(sDO.element_type)
            if active:
                leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx])
                if leaf_entry >= Int32(0):
                    query_idx = Int32(mLeafQueryIndex[leaf_entry])
                    do_val = mGradReadout[query_idx, head_idx, dim_idx]
            sDO[row_idx, dim_idx] = do_val
        for elem_idx in cutlass.range(lane, Int32(8) * Int32(64), cute.arch.WARP_SIZE, unroll=1):
            value_slot = elem_idx // Int32(64)
            dim_idx = elem_idx - value_slot * Int32(64)
            v_val = Float32(0.0).to(sV.element_type)
            if active:
                value_idx = Int32(mPackValueIndex[pack_idx, value_slot])
                v_val = mValue[value_idx, head_idx, dim_idx]
            sV[value_slot, dim_idx] = v_val
        cute.arch.sync_warp()

        if active:
            tiled_mma = cute.make_tiled_mma(
                warp.MmaF16BF16Op(mGradReadout.element_type, Float32, (16, 8, 16)),
                (1, 1, 1),
                permutation_mnk=(16, 8, 16),
            )
            thr_mma = tiled_mma.get_slice(lane)
            smem_copy_atom = cute.make_copy_atom(
                warp.LdMatrix8x8x16bOp(transpose=False, num_matrices=4),
                mGradReadout.element_type,
            )
            smem_thr_copy_do = cute_utils.make_tiled_copy_A(smem_copy_atom, tiled_mma).get_slice(lane)
            smem_thr_copy_v = cute_utils.make_tiled_copy_B(smem_copy_atom, tiled_mma).get_slice(lane)
            tSrDO = cute_utils.mma_make_fragment_A(sDO, thr_mma)
            tSrV = cute_utils.mma_make_fragment_B(sV, thr_mma)
            tSsDO = smem_thr_copy_do.partition_S(sDO)
            tSsV = smem_thr_copy_v.partition_S(sV)
            acc_shape = thr_mma.partition_shape_C((16, 8))
            c_tile = cute.make_identity_tensor((16, 8))
            tCc = layout_utils.reshape_acc_to_mn(thr_mma.partition_C(c_tile))
            acc = cute.make_fragment(acc_shape, Float32)
            acc.fill(0.0)
            sm80_utils.gemm(
                thr_mma,
                acc,
                tSrDO,
                tSrV,
                tSsDO,
                tSsV,
                smem_thr_copy_do,
                smem_thr_copy_v,
            )
            acc_mn = layout_utils.reshape_acc_to_mn(acc)
            for mi in cutlass.range_constexpr(cute.size(tCc.shape[0])):
                for ni in cutlass.range_constexpr(cute.size(tCc.shape[1])):
                    row_idx = tCc[mi, ni][0]
                    value_slot = tCc[mi, ni][1]
                    leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx])
                    wanted_slot = Int32(mPackValueSlot[pack_idx, row_idx])
                    if leaf_entry >= Int32(0) and value_slot == wanted_slot:
                        grad_attn = acc_mn[mi, ni]
                        mLeafGradAttn[leaf_entry, head_idx] = grad_attn.to(mLeafGradAttn.element_type)


class ARHSALeafGradAttnQueryValuePackedTensorCoreD64Sm100:
    """Query/value packed dO dot V pass using useful 16x8 MMA outputs."""

    arch = 100

    def __init__(self, *, num_threads: int = 128, max_values: int = 8):
        if int(max_values) not in (8, 16):
            raise ValueError("max_values must be 8 or 16")
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32
        self.max_values = int(max_values)
        self.value_tiles = int(max_values) // 8

    @cute.jit
    def __call__(
        self,
        mPackQueryIndex: cute.Tensor,
        mPackValueIndex: cute.Tensor,
        mPackLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.warps_per_cta)
        self.kernel(
            mPackQueryIndex,
            mPackValueIndex,
            mPackLeafEntryIndex,
            mValue,
            mGradReadout,
            mLeafGradAttn,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mPackQueryIndex: cute.Tensor,
        mPackValueIndex: cute.Tensor,
        mPackLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        task_idx = block_idx * Int32(self.warps_per_cta) + warp_idx
        active = task_idx < total_tasks
        num_heads = Int32(mValue.shape[1])
        pack_idx = Int32(0)
        head_idx = Int32(0)
        if active:
            pack_idx = task_idx // num_heads
            head_idx = task_idx - pack_idx * num_heads

        smem = cutlass.utils.SmemAllocator()
        sDOAll = smem.allocate_tensor(
            mGradReadout.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mGradReadout.element_type, 64),
                (self.warps_per_cta * 16, 64),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sVAll = smem.allocate_tensor(
            mValue.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mValue.element_type, 64),
                (self.warps_per_cta * 8, 64),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sDO = cute.local_tile(sDOAll, (16, 64), (warp_idx, 0))
        sV = cute.local_tile(sVAll, (8, 64), (warp_idx, 0))

        for elem_idx in cutlass.range(lane, Int32(16) * Int32(64), cute.arch.WARP_SIZE, unroll=1):
            row_idx = elem_idx // Int32(64)
            dim_idx = elem_idx - row_idx * Int32(64)
            do_val = Float32(0.0).to(sDO.element_type)
            if active:
                query_idx = Int32(mPackQueryIndex[pack_idx, row_idx])
                if query_idx >= Int32(0):
                    do_val = mGradReadout[query_idx, head_idx, dim_idx]
            sDO[row_idx, dim_idx] = do_val
        cute.arch.sync_warp()

        if active:
            for value_tile in cutlass.range_constexpr(self.value_tiles):
                value_base = Int32(value_tile) * Int32(8)
                for elem_idx in cutlass.range(lane, Int32(8) * Int32(64), cute.arch.WARP_SIZE, unroll=1):
                    value_slot = elem_idx // Int32(64)
                    dim_idx = elem_idx - value_slot * Int32(64)
                    v_val = Float32(0.0).to(sV.element_type)
                    value_idx = Int32(mPackValueIndex[pack_idx, value_base + value_slot])
                    v_val = mValue[value_idx, head_idx, dim_idx]
                    sV[value_slot, dim_idx] = v_val
                cute.arch.sync_warp()

                tiled_mma = cute.make_tiled_mma(
                    warp.MmaF16BF16Op(mGradReadout.element_type, Float32, (16, 8, 16)),
                    (1, 1, 1),
                    permutation_mnk=(16, 8, 16),
                )
                thr_mma = tiled_mma.get_slice(lane)
                smem_copy_atom = cute.make_copy_atom(
                    warp.LdMatrix8x8x16bOp(transpose=False, num_matrices=4),
                    mGradReadout.element_type,
                )
                smem_thr_copy_do = cute_utils.make_tiled_copy_A(smem_copy_atom, tiled_mma).get_slice(lane)
                smem_thr_copy_v = cute_utils.make_tiled_copy_B(smem_copy_atom, tiled_mma).get_slice(lane)
                tSrDO = cute_utils.mma_make_fragment_A(sDO, thr_mma)
                tSrV = cute_utils.mma_make_fragment_B(sV, thr_mma)
                tSsDO = smem_thr_copy_do.partition_S(sDO)
                tSsV = smem_thr_copy_v.partition_S(sV)
                acc_shape = thr_mma.partition_shape_C((16, 8))
                c_tile = cute.make_identity_tensor((16, 8))
                tCc = layout_utils.reshape_acc_to_mn(thr_mma.partition_C(c_tile))
                acc = cute.make_fragment(acc_shape, Float32)
                acc.fill(0.0)
                sm80_utils.gemm(
                    thr_mma,
                    acc,
                    tSrDO,
                    tSrV,
                    tSsDO,
                    tSsV,
                    smem_thr_copy_do,
                    smem_thr_copy_v,
                )
                acc_mn = layout_utils.reshape_acc_to_mn(acc)
                for mi in cutlass.range_constexpr(cute.size(tCc.shape[0])):
                    for ni in cutlass.range_constexpr(cute.size(tCc.shape[1])):
                        row_idx = tCc[mi, ni][0]
                        value_slot = tCc[mi, ni][1]
                        leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx, value_base + value_slot])
                        if leaf_entry >= Int32(0):
                            grad_attn = acc_mn[mi, ni]
                            mLeafGradAttn[leaf_entry, head_idx] = grad_attn.to(mLeafGradAttn.element_type)


class ARHSALeafReadoutBackwardStatsFromLeafGradQueryWarpSm100:
    """Query/head-owned stats reduction over precomputed leaf_grad_attn."""

    arch = 100

    def __init__(self, *, num_threads: int = 128):
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.warps_per_cta)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mQueryLeafRowPtr,
            mQueryLeafEntryIndex,
            mLeafGradAttn,
            mDenom,
            mWeightedGradSum,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        task_idx = block_idx * Int32(self.warps_per_cta) + warp_idx
        if task_idx < total_tasks:
            num_heads = Int32(mP.shape[1])
            query_idx = task_idx // num_heads
            head_idx = task_idx - query_idx * num_heads
            start = Int32(mQueryLeafRowPtr[query_idx])
            end = Int32(mQueryLeafRowPtr[query_idx + 1])
            denom_partial = Float32.zero
            weighted_partial = Float32.zero
            for ptr in cutlass.range(start + lane, end, cute.arch.WARP_SIZE, unroll=1):
                leaf_entry = Int32(mQueryLeafEntryIndex[ptr])
                node_idx = Int32(mLeafNodeIndex[leaf_entry])
                mass = Float32(mP[node_idx, head_idx])
                grad_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                denom_partial += mass
                weighted_partial += mass * grad_attn
            denom = cute_utils.warp_reduce(denom_partial, lambda a, b: a + b, width=32)
            weighted_grad_sum = cute_utils.warp_reduce(weighted_partial, lambda a, b: a + b, width=32)
            if lane == Int32(0):
                if denom < Float32(1.0e-8):
                    denom = Float32(1.0e-8)
                mDenom[query_idx, head_idx] = denom.to(mDenom.element_type)
                mWeightedGradSum[query_idx, head_idx] = weighted_grad_sum.to(
                    mWeightedGradSum.element_type
                )


class ARHSALeafReadoutBackwardStatsQueryWarpSm100:
    """Query/head-owned warp stats pass for small leaf fanout."""

    arch = 100

    def __init__(self, *, num_threads: int = 128, head_dim_is_64: bool = False):
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32
        self.head_dim_is_64 = head_dim_is_64

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        if cutlass.const_expr(self.head_dim_is_64):
            grid_x = cute.ceil_div(total_tasks, self.warps_per_cta * 2)
        else:
            grid_x = cute.ceil_div(total_tasks, self.warps_per_cta)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mLeafValueIndex,
            mQueryLeafRowPtr,
            mQueryLeafEntryIndex,
            mValue,
            mGradReadout,
            mLeafGradAttn,
            mDenom,
            mWeightedGradSum,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        if cutlass.const_expr(self.head_dim_is_64):
            half_warp = lane // Int32(16)
            lane16 = lane - half_warp * Int32(16)
            task_idx = block_idx * Int32(self.warps_per_cta * 2) + warp_idx * Int32(2) + half_warp
            if task_idx < total_tasks:
                num_heads = Int32(mP.shape[1])
                query_idx = task_idx // num_heads
                head_idx = task_idx - query_idx * num_heads
                start = Int32(mQueryLeafRowPtr[query_idx])
                end = Int32(mQueryLeafRowPtr[query_idx + 1])
                leaf_count = end - start

                denom_partial = Float32.zero
                for leaf_offset in cutlass.range(lane16, leaf_count, Int32(16), unroll=1):
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_offset])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    denom_partial += Float32(mP[node_idx, head_idx])
                denom = cute_utils.warp_reduce(denom_partial, lambda a, b: a + b, width=16)

                dim0 = lane16 * Int32(4)
                dim1 = dim0 + Int32(1)
                dim2 = dim0 + Int32(2)
                dim3 = dim0 + Int32(3)
                d0 = Float32(mGradReadout[query_idx, head_idx, dim0])
                d1 = Float32(mGradReadout[query_idx, head_idx, dim1])
                d2 = Float32(mGradReadout[query_idx, head_idx, dim2])
                d3 = Float32(mGradReadout[query_idx, head_idx, dim3])
                weighted_grad_sum = Float32.zero

                for ptr in cutlass.range(start, end, unroll=1):
                    leaf_entry = Int32(mQueryLeafEntryIndex[ptr])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    partial = d0 * Float32(mValue[value_idx, head_idx, dim0])
                    partial += d1 * Float32(mValue[value_idx, head_idx, dim1])
                    partial += d2 * Float32(mValue[value_idx, head_idx, dim2])
                    partial += d3 * Float32(mValue[value_idx, head_idx, dim3])
                    grad_attn = cute_utils.warp_reduce(partial, lambda a, b: a + b, width=16)
                    if lane16 == Int32(0):
                        node_idx = Int32(mLeafNodeIndex[leaf_entry])
                        mass = Float32(mP[node_idx, head_idx])
                        mLeafGradAttn[leaf_entry, head_idx] = grad_attn.to(mLeafGradAttn.element_type)
                        weighted_grad_sum += mass * grad_attn

                if lane16 == Int32(0):
                    if denom < Float32(1.0e-8):
                        denom = Float32(1.0e-8)
                    mDenom[query_idx, head_idx] = denom.to(mDenom.element_type)
                    mWeightedGradSum[query_idx, head_idx] = weighted_grad_sum.to(
                        mWeightedGradSum.element_type
                    )
        else:
            task_idx = block_idx * Int32(self.warps_per_cta) + warp_idx
            if task_idx < total_tasks:
                num_heads = Int32(mP.shape[1])
                head_dim_v = Int32(mValue.shape[2])
                query_idx = task_idx // num_heads
                head_idx = task_idx - query_idx * num_heads
                start = Int32(mQueryLeafRowPtr[query_idx])
                end = Int32(mQueryLeafRowPtr[query_idx + 1])

                denom = Float32.zero
                weighted_grad_sum = Float32.zero

                for ptr in cutlass.range(start, end, unroll=1):
                    leaf_entry = Int32(mQueryLeafEntryIndex[ptr])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    mass = Float32(mP[node_idx, head_idx])
                    partial = Float32.zero
                    for dim_idx in cutlass.range(lane, head_dim_v, cute.arch.WARP_SIZE, unroll=2):
                        partial += Float32(mGradReadout[query_idx, head_idx, dim_idx]) * Float32(
                            mValue[value_idx, head_idx, dim_idx]
                        )
                    grad_attn = cute_utils.warp_reduce(partial, lambda a, b: a + b)
                    if lane == Int32(0):
                        mLeafGradAttn[leaf_entry, head_idx] = grad_attn.to(mLeafGradAttn.element_type)
                    denom += mass
                    weighted_grad_sum += mass * grad_attn

                if lane == Int32(0):
                    if denom < Float32(1.0e-8):
                        denom = Float32(1.0e-8)
                    mDenom[query_idx, head_idx] = denom.to(mDenom.element_type)
                    mWeightedGradSum[query_idx, head_idx] = weighted_grad_sum.to(
                        mWeightedGradSum.element_type
                    )


class ARHSALeafReadoutBackwardStatsTensorCoreD64Sm100:
    """Experimental D=64 stats pass using one warp-level MMA per query/head.

    This pads a single query/head into a 16x8x64 MMA tile and uses only row 0 of
    the M dimension. It is useful for measuring whether tensor cores help the
    per-leaf dO dot V inner products despite the row-specific leaf set.
    """

    arch = 100

    def __init__(self, *, num_threads: int = 128):
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.warps_per_cta)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mLeafValueIndex,
            mQueryLeafRowPtr,
            mQueryLeafEntryIndex,
            mValue,
            mGradReadout,
            mLeafGradAttn,
            mDenom,
            mWeightedGradSum,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        task_idx = block_idx * Int32(self.warps_per_cta) + warp_idx
        active = task_idx < total_tasks
        num_heads = Int32(mP.shape[1])
        query_idx = Int32(0)
        head_idx = Int32(0)
        start = Int32(0)
        end = Int32(0)
        leaf_count = Int32(0)
        if active:
            num_heads = Int32(mP.shape[1])
            query_idx = task_idx // num_heads
            head_idx = task_idx - query_idx * num_heads
            start = Int32(mQueryLeafRowPtr[query_idx])
            end = Int32(mQueryLeafRowPtr[query_idx + 1])
            leaf_count = end - start

        smem = cutlass.utils.SmemAllocator()
        sDOAll = smem.allocate_tensor(
            mGradReadout.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mGradReadout.element_type, 64),
                (self.warps_per_cta * 16, 64),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sVAll = smem.allocate_tensor(
            mValue.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mValue.element_type, 64),
                (self.warps_per_cta * 8, 64),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sGradAttnAll = smem.allocate_tensor(
            Float32,
            cute.make_layout((self.warps_per_cta, 8)),
            byte_alignment=16,
        )
        sDO = cute.local_tile(sDOAll, (16, 64), (warp_idx, 0))
        sV = cute.local_tile(sVAll, (8, 64), (warp_idx, 0))
        sGradAttn = sGradAttnAll[warp_idx, None]

        # Only C row 0 is consumed, so rows 1-15 of A do not need initialization.
        for dim_idx in cutlass.range(lane, Int32(64), cute.arch.WARP_SIZE, unroll=1):
            do_val = Float32(0.0).to(sDO.element_type)
            if active:
                do_val = mGradReadout[query_idx, head_idx, dim_idx]
            sDO[Int32(0), dim_idx] = do_val
        for elem_idx in cutlass.range(lane, Int32(8) * Int32(64), cute.arch.WARP_SIZE, unroll=1):
            leaf_slot = elem_idx // Int32(64)
            dim_idx = elem_idx - leaf_slot * Int32(64)
            v_val = Float32(0.0).to(sV.element_type)
            if active:
                if leaf_slot < leaf_count:
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_slot])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    v_val = mValue[value_idx, head_idx, dim_idx]
            sV[leaf_slot, dim_idx] = v_val
        if lane < Int32(8):
            sGradAttn[lane] = Float32(0.0)
        cute.arch.barrier()

        if active:
            tiled_mma = cute.make_tiled_mma(
                warp.MmaF16BF16Op(mGradReadout.element_type, Float32, (16, 8, 16)),
                (1, 1, 1),
                permutation_mnk=(16, 8, 16),
            )
            thr_mma = tiled_mma.get_slice(lane)
            smem_copy_atom = cute.make_copy_atom(
                warp.LdMatrix8x8x16bOp(transpose=False, num_matrices=4),
                mGradReadout.element_type,
            )
            smem_thr_copy_do = cute_utils.make_tiled_copy_A(smem_copy_atom, tiled_mma).get_slice(lane)
            smem_thr_copy_v = cute_utils.make_tiled_copy_B(smem_copy_atom, tiled_mma).get_slice(lane)
            tSrDO = cute_utils.mma_make_fragment_A(sDO, thr_mma)
            tSrV = cute_utils.mma_make_fragment_B(sV, thr_mma)
            tSsDO = smem_thr_copy_do.partition_S(sDO)
            tSsV = smem_thr_copy_v.partition_S(sV)
            acc_shape = thr_mma.partition_shape_C((16, 8))
            c_tile = cute.make_identity_tensor((16, 8))
            tCc = layout_utils.reshape_acc_to_mn(thr_mma.partition_C(c_tile))
            acc = cute.make_fragment(acc_shape, Float32)
            acc.fill(0.0)
            sm80_utils.gemm(
                thr_mma,
                acc,
                tSrDO,
                tSrV,
                tSsDO,
                tSsV,
                smem_thr_copy_do,
                smem_thr_copy_v,
            )
            acc_mn = layout_utils.reshape_acc_to_mn(acc)
            for mi in cutlass.range_constexpr(cute.size(tCc.shape[0])):
                for ni in cutlass.range_constexpr(cute.size(tCc.shape[1])):
                    row_idx = tCc[mi, ni][0]
                    leaf_slot = tCc[mi, ni][1]
                    if row_idx == Int32(0) and leaf_slot < leaf_count:
                        sGradAttn[leaf_slot] = acc_mn[mi, ni]
        cute.arch.barrier()

        if active and lane == Int32(0):
            denom = Float32.zero
            weighted_grad_sum = Float32.zero
            for leaf_slot in cutlass.range(Int32(0), leaf_count, unroll=1):
                leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_slot])
                node_idx = Int32(mLeafNodeIndex[leaf_entry])
                mass = Float32(mP[node_idx, head_idx])
                grad_attn = Float32(sGradAttn[leaf_slot])
                denom += mass
                weighted_grad_sum += mass * grad_attn
                mLeafGradAttn[leaf_entry, head_idx] = grad_attn.to(mLeafGradAttn.element_type)
            if denom < Float32(1.0e-8):
                denom = Float32(1.0e-8)
            mDenom[query_idx, head_idx] = denom.to(mDenom.element_type)
            mWeightedGradSum[query_idx, head_idx] = weighted_grad_sum.to(mWeightedGradSum.element_type)


class ARHSALeafReadoutBackwardFusedTensorCoreD64Sm100:
    """Experimental fused D=64 readout backward with tensor-core dO dot V stats."""

    arch = 100

    def __init__(self, *, num_threads: int = 64):
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.warps_per_cta)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mLeafValueIndex,
            mQueryLeafRowPtr,
            mQueryLeafEntryIndex,
            mValue,
            mGradReadout,
            mGradP,
            mGradValue,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        task_idx = block_idx * Int32(self.warps_per_cta) + warp_idx
        active = task_idx < total_tasks
        num_heads = Int32(mP.shape[1])
        query_idx = Int32(0)
        head_idx = Int32(0)
        start = Int32(0)
        end = Int32(0)
        leaf_count = Int32(0)
        if active:
            query_idx = task_idx // num_heads
            head_idx = task_idx - query_idx * num_heads
            start = Int32(mQueryLeafRowPtr[query_idx])
            end = Int32(mQueryLeafRowPtr[query_idx + 1])
            leaf_count = end - start

        smem = cutlass.utils.SmemAllocator()
        sDOAll = smem.allocate_tensor(
            mGradReadout.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mGradReadout.element_type, 64),
                (self.warps_per_cta * 16, 64),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sVAll = smem.allocate_tensor(
            mValue.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mValue.element_type, 64),
                (self.warps_per_cta * 8, 64),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sGradAttnAll = smem.allocate_tensor(
            Float32,
            cute.make_layout((self.warps_per_cta, 8)),
            byte_alignment=16,
        )
        sStatsAll = smem.allocate_tensor(
            Float32,
            cute.make_layout((self.warps_per_cta, 2)),
            byte_alignment=16,
        )
        sDO = cute.local_tile(sDOAll, (16, 64), (warp_idx, 0))
        sV = cute.local_tile(sVAll, (8, 64), (warp_idx, 0))
        sGradAttn = sGradAttnAll[warp_idx, None]
        sStats = sStatsAll[warp_idx, None]

        # Only C row 0 is consumed, so rows 1-15 of A do not need initialization.
        for dim_idx in cutlass.range(lane, Int32(64), cute.arch.WARP_SIZE, unroll=1):
            do_val = Float32(0.0).to(sDO.element_type)
            if active:
                do_val = mGradReadout[query_idx, head_idx, dim_idx]
            sDO[Int32(0), dim_idx] = do_val
        for elem_idx in cutlass.range(lane, Int32(8) * Int32(64), cute.arch.WARP_SIZE, unroll=1):
            leaf_slot = elem_idx // Int32(64)
            dim_idx = elem_idx - leaf_slot * Int32(64)
            v_val = Float32(0.0).to(sV.element_type)
            if active:
                if leaf_slot < leaf_count:
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_slot])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    v_val = mValue[value_idx, head_idx, dim_idx]
            sV[leaf_slot, dim_idx] = v_val
        if lane < Int32(8):
            sGradAttn[lane] = Float32(0.0)
        if lane < Int32(2):
            sStats[lane] = Float32(0.0)
        cute.arch.barrier()

        if active:
            tiled_mma = cute.make_tiled_mma(
                warp.MmaF16BF16Op(mGradReadout.element_type, Float32, (16, 8, 16)),
                (1, 1, 1),
                permutation_mnk=(16, 8, 16),
            )
            thr_mma = tiled_mma.get_slice(lane)
            smem_copy_atom = cute.make_copy_atom(
                warp.LdMatrix8x8x16bOp(transpose=False, num_matrices=4),
                mGradReadout.element_type,
            )
            smem_thr_copy_do = cute_utils.make_tiled_copy_A(smem_copy_atom, tiled_mma).get_slice(lane)
            smem_thr_copy_v = cute_utils.make_tiled_copy_B(smem_copy_atom, tiled_mma).get_slice(lane)
            tSrDO = cute_utils.mma_make_fragment_A(sDO, thr_mma)
            tSrV = cute_utils.mma_make_fragment_B(sV, thr_mma)
            tSsDO = smem_thr_copy_do.partition_S(sDO)
            tSsV = smem_thr_copy_v.partition_S(sV)
            acc_shape = thr_mma.partition_shape_C((16, 8))
            c_tile = cute.make_identity_tensor((16, 8))
            tCc = layout_utils.reshape_acc_to_mn(thr_mma.partition_C(c_tile))
            acc = cute.make_fragment(acc_shape, Float32)
            acc.fill(0.0)
            sm80_utils.gemm(
                thr_mma,
                acc,
                tSrDO,
                tSrV,
                tSsDO,
                tSsV,
                smem_thr_copy_do,
                smem_thr_copy_v,
            )
            acc_mn = layout_utils.reshape_acc_to_mn(acc)
            for mi in cutlass.range_constexpr(cute.size(tCc.shape[0])):
                for ni in cutlass.range_constexpr(cute.size(tCc.shape[1])):
                    row_idx = tCc[mi, ni][0]
                    leaf_slot = tCc[mi, ni][1]
                    if row_idx == Int32(0) and leaf_slot < leaf_count:
                        sGradAttn[leaf_slot] = acc_mn[mi, ni]
        cute.arch.barrier()

        if active:
            if lane == Int32(0):
                denom = Float32.zero
                weighted_grad_sum = Float32.zero
                for leaf_slot in cutlass.range(Int32(0), leaf_count, unroll=1):
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_slot])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    mass = Float32(mP[node_idx, head_idx])
                    grad_attn = Float32(sGradAttn[leaf_slot])
                    denom += mass
                    weighted_grad_sum += mass * grad_attn
                if denom < Float32(1.0e-8):
                    denom = Float32(1.0e-8)
                inv_denom = Float32(1.0) / denom
                sStats[0] = inv_denom
                sStats[1] = weighted_grad_sum * inv_denom
        cute.arch.barrier()

        if active:
            inv_denom = Float32(sStats[0])
            weighted_grad_mean = Float32(sStats[1])
            if lane < leaf_count:
                leaf_entry = Int32(mQueryLeafEntryIndex[start + lane])
                node_idx = Int32(mLeafNodeIndex[leaf_entry])
                grad_attn = Float32(sGradAttn[lane])
                grad_mass = (grad_attn - weighted_grad_mean) * inv_denom
                cute_utils.atomic_add_fp32(
                    grad_mass,
                    cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
                )

            leaf_lane = lane // Int32(16)
            dim_group = lane - leaf_lane * Int32(16)
            for leaf_base in cutlass.range(Int32(0), leaf_count, Int32(2), unroll=1):
                leaf_offset = leaf_base + leaf_lane
                if leaf_offset < leaf_count:
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_offset])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    mass = Float32(mP[node_idx, head_idx])
                    attn = mass * inv_denom
                    dim0 = dim_group * Int32(4)
                    dim1 = dim0 + Int32(1)
                    dim2 = dim0 + Int32(2)
                    dim3 = dim0 + Int32(3)
                    copy_utils.atomic_add_fp32x4(
                        attn * Float32(mGradReadout[query_idx, head_idx, dim0]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim1]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim2]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim3]),
                        cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
                    )


class ARHSALeafReadoutBackwardScatterSm100:
    """Scatter direct leaf readout gradients using cached query/head stats."""

    arch = 100

    def __init__(self, *, num_threads: int = 256, vectorize_dim4: bool = False):
        self.num_threads = num_threads
        self.vectorize_dim4 = vectorize_dim4

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafQueryIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.num_threads)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mLeafQueryIndex,
            mLeafValueIndex,
            mValue,
            mGradReadout,
            mLeafGradAttn,
            mDenom,
            mWeightedGradSum,
            mGradP,
            mGradValue,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafQueryIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        task_idx = block_idx * self.num_threads + tidx
        if task_idx < total_tasks:
            num_heads = Int32(mP.shape[1])
            head_dim_v = Int32(mValue.shape[2])
            leaf_entry = task_idx // num_heads
            head_idx = task_idx - leaf_entry * num_heads
            query_idx = Int32(mLeafQueryIndex[leaf_entry])
            node_idx = Int32(mLeafNodeIndex[leaf_entry])
            value_idx = Int32(mLeafValueIndex[leaf_entry])
            denom = Float32(mDenom[query_idx, head_idx])
            if denom < Float32(1.0e-8):
                denom = Float32(1.0e-8)
            weighted_grad_sum = Float32(mWeightedGradSum[query_idx, head_idx])
            grad_leaf_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
            grad_mass = (grad_leaf_attn - weighted_grad_sum / denom) / denom
            cute_utils.atomic_add_fp32(
                grad_mass,
                cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
            )

            attn = Float32(mP[node_idx, head_idx]) / denom
            if cutlass.const_expr(self.vectorize_dim4):
                for dim_group in cutlass.range(head_dim_v // Int32(4), unroll=4):
                    dim0 = dim_group * Int32(4)
                    dim1 = dim0 + Int32(1)
                    dim2 = dim0 + Int32(2)
                    dim3 = dim0 + Int32(3)
                    copy_utils.atomic_add_fp32x4(
                        attn * Float32(mGradReadout[query_idx, head_idx, dim0]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim1]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim2]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim3]),
                        cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
                    )
            else:
                for dim_idx in cutlass.range(head_dim_v, unroll=16):
                    cute_utils.atomic_add_fp32(
                        attn * Float32(mGradReadout[query_idx, head_idx, dim_idx]),
                        cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim_idx)),
                    )


class ARHSALeafReadoutBackwardScatterQueryWarpSm100:
    """Query/head-owned scatter pass that parallelizes value-dim atomics across a warp."""

    arch = 100

    def __init__(
        self,
        *,
        num_threads: int = 128,
        vectorize_dim4: bool = False,
        head_dim_is_64: bool = False,
    ):
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32
        self.vectorize_dim4 = vectorize_dim4
        self.head_dim_is_64 = head_dim_is_64

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.warps_per_cta)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mLeafValueIndex,
            mQueryLeafRowPtr,
            mQueryLeafEntryIndex,
            mGradReadout,
            mLeafGradAttn,
            mDenom,
            mWeightedGradSum,
            mGradP,
            mGradValue,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mDenom: cute.Tensor,
        mWeightedGradSum: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        task_idx = block_idx * Int32(self.warps_per_cta) + warp_idx
        if task_idx < total_tasks:
            num_heads = Int32(mP.shape[1])
            head_dim_v = Int32(mGradReadout.shape[2])
            query_idx = task_idx // num_heads
            head_idx = task_idx - query_idx * num_heads
            start = Int32(mQueryLeafRowPtr[query_idx])
            end = Int32(mQueryLeafRowPtr[query_idx + 1])
            leaf_count = end - start
            denom = Float32(mDenom[query_idx, head_idx])
            if denom < Float32(1.0e-8):
                denom = Float32(1.0e-8)
            weighted_grad_sum = Float32(mWeightedGradSum[query_idx, head_idx])

            if cutlass.const_expr(self.head_dim_is_64):
                leaf_lane = lane // Int32(16)
                dim_group = lane - leaf_lane * Int32(16)
                for leaf_base in cutlass.range(Int32(0), leaf_count, Int32(2), unroll=1):
                    leaf_offset = leaf_base + leaf_lane
                    if leaf_offset < leaf_count:
                        leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_offset])
                        node_idx = Int32(mLeafNodeIndex[leaf_entry])
                        value_idx = Int32(mLeafValueIndex[leaf_entry])
                        mass = Float32(mP[node_idx, head_idx])
                        if dim_group == Int32(0):
                            grad_leaf_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                            grad_mass = (grad_leaf_attn - weighted_grad_sum / denom) / denom
                            cute_utils.atomic_add_fp32(
                                grad_mass,
                                cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
                            )

                        attn = mass / denom
                        dim0 = dim_group * Int32(4)
                        dim1 = dim0 + Int32(1)
                        dim2 = dim0 + Int32(2)
                        dim3 = dim0 + Int32(3)
                        copy_utils.atomic_add_fp32x4(
                            attn * Float32(mGradReadout[query_idx, head_idx, dim0]),
                            attn * Float32(mGradReadout[query_idx, head_idx, dim1]),
                            attn * Float32(mGradReadout[query_idx, head_idx, dim2]),
                            attn * Float32(mGradReadout[query_idx, head_idx, dim3]),
                            cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
                        )
            else:
                for ptr in cutlass.range(start, end, unroll=1):
                    leaf_entry = Int32(mQueryLeafEntryIndex[ptr])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    mass = Float32(mP[node_idx, head_idx])
                    if lane == Int32(0):
                        grad_leaf_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                        grad_mass = (grad_leaf_attn - weighted_grad_sum / denom) / denom
                        cute_utils.atomic_add_fp32(
                            grad_mass,
                            cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
                        )

                    attn = mass / denom
                    if cutlass.const_expr(self.vectorize_dim4):
                        for dim_group in cutlass.range(lane, head_dim_v // Int32(4), cute.arch.WARP_SIZE, unroll=1):
                            dim0 = dim_group * Int32(4)
                            dim1 = dim0 + Int32(1)
                            dim2 = dim0 + Int32(2)
                            dim3 = dim0 + Int32(3)
                            copy_utils.atomic_add_fp32x4(
                                attn * Float32(mGradReadout[query_idx, head_idx, dim0]),
                                attn * Float32(mGradReadout[query_idx, head_idx, dim1]),
                                attn * Float32(mGradReadout[query_idx, head_idx, dim2]),
                                attn * Float32(mGradReadout[query_idx, head_idx, dim3]),
                                cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
                            )
                    else:
                        for dim_idx in cutlass.range(lane, head_dim_v, cute.arch.WARP_SIZE, unroll=2):
                            cute_utils.atomic_add_fp32(
                                attn * Float32(mGradReadout[query_idx, head_idx, dim_idx]),
                            cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim_idx)),
                        )


class ARHSALeafReadoutBackwardScatterFromLeafGradQueryWarpD64Sm100:
    """Query/head-owned D=64 scatter that derives stats from cached leaf_grad_attn."""

    arch = 100

    def __init__(self, *, num_threads: int = 128):
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.warps_per_cta)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mLeafValueIndex,
            mQueryLeafRowPtr,
            mQueryLeafEntryIndex,
            mGradReadout,
            mLeafGradAttn,
            mGradP,
            mGradValue,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        task_idx = block_idx * Int32(self.warps_per_cta) + warp_idx
        if task_idx < total_tasks:
            num_heads = Int32(mP.shape[1])
            query_idx = task_idx // num_heads
            head_idx = task_idx - query_idx * num_heads
            start = Int32(mQueryLeafRowPtr[query_idx])
            end = Int32(mQueryLeafRowPtr[query_idx + 1])
            leaf_count = end - start

            denom_partial = Float32.zero
            weighted_partial = Float32.zero
            for ptr in cutlass.range(start + lane, end, cute.arch.WARP_SIZE, unroll=1):
                leaf_entry = Int32(mQueryLeafEntryIndex[ptr])
                node_idx = Int32(mLeafNodeIndex[leaf_entry])
                mass = Float32(mP[node_idx, head_idx])
                grad_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                denom_partial += mass
                weighted_partial += mass * grad_attn
            denom = cute_utils.warp_reduce(denom_partial, lambda a, b: a + b, width=32)
            weighted_grad_sum = cute_utils.warp_reduce(weighted_partial, lambda a, b: a + b, width=32)
            if denom < Float32(1.0e-8):
                denom = Float32(1.0e-8)
            inv_denom = Float32(1.0) / denom
            weighted_grad_mean = weighted_grad_sum * inv_denom

            if lane < leaf_count:
                leaf_entry = Int32(mQueryLeafEntryIndex[start + lane])
                node_idx = Int32(mLeafNodeIndex[leaf_entry])
                grad_leaf_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                grad_mass = (grad_leaf_attn - weighted_grad_mean) * inv_denom
                cute_utils.atomic_add_fp32(
                    grad_mass,
                    cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
                )

            leaf_lane = lane // Int32(16)
            dim_group = lane - leaf_lane * Int32(16)
            for leaf_base in cutlass.range(Int32(0), leaf_count, Int32(2), unroll=1):
                leaf_offset = leaf_base + leaf_lane
                if leaf_offset < leaf_count:
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_offset])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    mass = Float32(mP[node_idx, head_idx])
                    attn = mass * inv_denom
                    dim0 = dim_group * Int32(4)
                    dim1 = dim0 + Int32(1)
                    dim2 = dim0 + Int32(2)
                    dim3 = dim0 + Int32(3)
                    copy_utils.atomic_add_fp32x4(
                        attn * Float32(mGradReadout[query_idx, head_idx, dim0]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim1]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim2]),
                        attn * Float32(mGradReadout[query_idx, head_idx, dim3]),
                        cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
                    )


class ARHSALeafReadoutBackwardScatterFromQueryValuePackD64Sm100:
    """Pack-owned qv scatter for D=64 that reduces grad_value atomics across rows."""

    arch = 100

    def __init__(self, *, num_threads: int = 128, max_values: int = 8):
        if int(max_values) not in (8, 16):
            raise ValueError("max_values must be 8 or 16")
        self.num_threads = num_threads
        self.max_values = int(max_values)

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mPackQueryIndex: cute.Tensor,
        mPackValueIndex: cute.Tensor,
        mPackLeafEntryIndex: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        self.kernel(
            mP,
            mLeafNodeIndex,
            mPackQueryIndex,
            mPackValueIndex,
            mPackLeafEntryIndex,
            mGradReadout,
            mLeafGradAttn,
            mGradP,
            mGradValue,
            total_tasks,
        ).launch(
            grid=[total_tasks, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mPackQueryIndex: cute.Tensor,
        mPackValueIndex: cute.Tensor,
        mPackLeafEntryIndex: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        task_idx = Int32(block_idx)
        active = task_idx < total_tasks
        num_heads = Int32(mP.shape[1])
        pack_idx = Int32(0)
        head_idx = Int32(0)
        if active:
            pack_idx = task_idx // num_heads
            head_idx = task_idx - pack_idx * num_heads

        smem = cutlass.utils.SmemAllocator()
        sStats = smem.allocate_tensor(
            Float32,
            cute.make_layout((16, 2)),
            byte_alignment=16,
        )
        sAttn = smem.allocate_tensor(
            Float32,
            cute.make_layout((16, self.max_values)),
            byte_alignment=16,
        )

        if tidx < Int32(16):
            row_idx = Int32(tidx)
            inv_denom = Float32.zero
            weighted_grad_mean = Float32.zero
            query_idx = Int32(mPackQueryIndex[pack_idx, row_idx])
            if query_idx >= Int32(0):
                denom = Float32.zero
                weighted_grad_sum = Float32.zero
                for value_slot in cutlass.range(Int32(0), Int32(self.max_values), unroll=1):
                    leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx, value_slot])
                    if leaf_entry >= Int32(0):
                        node_idx = Int32(mLeafNodeIndex[leaf_entry])
                        mass = Float32(mP[node_idx, head_idx])
                        grad_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                        denom += mass
                        weighted_grad_sum += mass * grad_attn
                if denom < Float32(1.0e-8):
                    denom = Float32(1.0e-8)
                inv_denom = Float32(1.0) / denom
                weighted_grad_mean = weighted_grad_sum * inv_denom
            sStats[row_idx, Int32(0)] = inv_denom
            sStats[row_idx, Int32(1)] = weighted_grad_mean
        cute.arch.barrier()

        for elem_idx in cutlass.range(tidx, Int32(16) * Int32(self.max_values), self.num_threads, unroll=1):
            row_idx = elem_idx // Int32(self.max_values)
            value_slot = elem_idx - row_idx * Int32(self.max_values)
            attn = Float32.zero
            if Int32(mPackQueryIndex[pack_idx, row_idx]) >= Int32(0):
                leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx, value_slot])
                if leaf_entry >= Int32(0):
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    attn = Float32(mP[node_idx, head_idx]) * Float32(sStats[row_idx, Int32(0)])
            sAttn[row_idx, value_slot] = attn
        cute.arch.barrier()

        for elem_idx in cutlass.range(tidx, Int32(16) * Int32(self.max_values), self.num_threads, unroll=1):
            row_idx = elem_idx // Int32(self.max_values)
            value_slot = elem_idx - row_idx * Int32(self.max_values)
            leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx, value_slot])
            if leaf_entry >= Int32(0):
                node_idx = Int32(mLeafNodeIndex[leaf_entry])
                grad_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                grad_mass = (grad_attn - Float32(sStats[row_idx, Int32(1)])) * Float32(
                    sStats[row_idx, Int32(0)]
                )
                cute_utils.atomic_add_fp32(
                    grad_mass,
                    cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
                )

        for elem_idx in cutlass.range(tidx, Int32(self.max_values) * Int32(16), self.num_threads, unroll=1):
            value_slot = elem_idx // Int32(16)
            dim_group = elem_idx - value_slot * Int32(16)
            dim0 = dim_group * Int32(4)
            dim1 = dim0 + Int32(1)
            dim2 = dim0 + Int32(2)
            dim3 = dim0 + Int32(3)
            value_idx = Int32(mPackValueIndex[pack_idx, value_slot])
            grad_value0 = Float32.zero
            grad_value1 = Float32.zero
            grad_value2 = Float32.zero
            grad_value3 = Float32.zero
            for row_idx in cutlass.range(Int32(0), Int32(16), unroll=1):
                leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx, value_slot])
                if leaf_entry >= Int32(0):
                    query_idx = Int32(mPackQueryIndex[pack_idx, row_idx])
                    attn = Float32(sAttn[row_idx, value_slot])
                    grad_value0 += attn * Float32(mGradReadout[query_idx, head_idx, dim0])
                    grad_value1 += attn * Float32(mGradReadout[query_idx, head_idx, dim1])
                    grad_value2 += attn * Float32(mGradReadout[query_idx, head_idx, dim2])
                    grad_value3 += attn * Float32(mGradReadout[query_idx, head_idx, dim3])
            copy_utils.atomic_add_fp32x4(
                grad_value0,
                grad_value1,
                grad_value2,
                grad_value3,
                cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
            )


class ARHSALeafReadoutBackwardScatterFromQueryValuePackTensorCoreD64Sm100:
    """Pack-owned qv scatter with tensor-core dV and scalar sparse dP."""

    arch = 100

    def __init__(self, *, num_threads: int = 256, max_values: int = 8):
        if int(max_values) not in (8, 16):
            raise ValueError("max_values must be 8 or 16")
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32
        self.max_values = int(max_values)

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mPackQueryIndex: cute.Tensor,
        mPackValueIndex: cute.Tensor,
        mPackLeafEntryIndex: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        self.kernel(
            mP,
            mLeafNodeIndex,
            mPackQueryIndex,
            mPackValueIndex,
            mPackLeafEntryIndex,
            mGradReadout,
            mLeafGradAttn,
            mGradP,
            mGradValue,
            total_tasks,
        ).launch(
            grid=[total_tasks, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mPackQueryIndex: cute.Tensor,
        mPackValueIndex: cute.Tensor,
        mPackLeafEntryIndex: cute.Tensor,
        mGradReadout: cute.Tensor,
        mLeafGradAttn: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        task_idx = Int32(block_idx)
        active = task_idx < total_tasks
        num_heads = Int32(mP.shape[1])
        pack_idx = Int32(0)
        head_idx = Int32(0)
        if active:
            pack_idx = task_idx // num_heads
            head_idx = task_idx - pack_idx * num_heads

        smem = cutlass.utils.SmemAllocator()
        sStats = smem.allocate_tensor(
            Float32,
            cute.make_layout((16, 2)),
            byte_alignment=16,
        )
        sAttnT = smem.allocate_tensor(
            mGradReadout.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mGradReadout.element_type, 16),
                (16, 16),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sDOAll = smem.allocate_tensor(
            mGradReadout.element_type,
            cute.tile_to_shape(
                sm80_utils.get_smem_layout_atom(mGradReadout.element_type, 16),
                (self.warps_per_cta * 8, 16),
                (0, 1),
            ),
            byte_alignment=16,
        )
        sGradValueAll = smem.allocate_tensor(
            Float32,
            cute.make_layout((self.warps_per_cta * 16, 8)),
            byte_alignment=16,
        )
        sDO = cute.local_tile(sDOAll, (8, 16), (warp_idx, 0))
        sGradValue = cute.local_tile(sGradValueAll, (16, 8), (warp_idx, 0))

        if tidx < Int32(16):
            row_idx = Int32(tidx)
            inv_denom = Float32.zero
            weighted_grad_mean = Float32.zero
            if active:
                query_idx = Int32(mPackQueryIndex[pack_idx, row_idx])
                if query_idx >= Int32(0):
                    denom = Float32.zero
                    weighted_grad_sum = Float32.zero
                    for value_slot in cutlass.range(Int32(0), Int32(self.max_values), unroll=1):
                        leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx, value_slot])
                        if leaf_entry >= Int32(0):
                            node_idx = Int32(mLeafNodeIndex[leaf_entry])
                            mass = Float32(mP[node_idx, head_idx])
                            grad_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                            denom += mass
                            weighted_grad_sum += mass * grad_attn
                    if denom < Float32(1.0e-8):
                        denom = Float32(1.0e-8)
                    inv_denom = Float32(1.0) / denom
                    weighted_grad_mean = weighted_grad_sum * inv_denom
            sStats[row_idx, Int32(0)] = inv_denom
            sStats[row_idx, Int32(1)] = weighted_grad_mean
        cute.arch.barrier()

        for elem_idx in cutlass.range(tidx, Int32(16) * Int32(16), self.num_threads, unroll=1):
            value_slot = elem_idx // Int32(16)
            row_idx = elem_idx - value_slot * Int32(16)
            attn = Float32.zero
            if active and value_slot < Int32(self.max_values) and Int32(mPackQueryIndex[pack_idx, row_idx]) >= Int32(0):
                leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx, value_slot])
                if leaf_entry >= Int32(0):
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    attn = Float32(mP[node_idx, head_idx]) * Float32(sStats[row_idx, Int32(0)])
            sAttnT[value_slot, row_idx] = attn.to(sAttnT.element_type)
        cute.arch.barrier()

        if active:
            for elem_idx in cutlass.range(tidx, Int32(16) * Int32(self.max_values), self.num_threads, unroll=1):
                row_idx = elem_idx // Int32(self.max_values)
                value_slot = elem_idx - row_idx * Int32(self.max_values)
                leaf_entry = Int32(mPackLeafEntryIndex[pack_idx, row_idx, value_slot])
                if leaf_entry >= Int32(0):
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    grad_attn = Float32(mLeafGradAttn[leaf_entry, head_idx])
                    grad_mass = (grad_attn - Float32(sStats[row_idx, Int32(1)])) * Float32(
                        sStats[row_idx, Int32(0)]
                    )
                    cute_utils.atomic_add_fp32(
                        grad_mass,
                        cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
                    )

        dim_tile = Int32(warp_idx)
        for elem_idx in cutlass.range(lane, Int32(16) * Int32(8), cute.arch.WARP_SIZE, unroll=1):
            value_slot = elem_idx // Int32(8)
            dim_local = elem_idx - value_slot * Int32(8)
            sGradValue[value_slot, dim_local] = Float32.zero
        for elem_idx in cutlass.range(lane, Int32(8) * Int32(16), cute.arch.WARP_SIZE, unroll=1):
            dim_local = elem_idx // Int32(16)
            row_idx = elem_idx - dim_local * Int32(16)
            do_val = Float32(0.0).to(sDO.element_type)
            if active:
                query_idx = Int32(mPackQueryIndex[pack_idx, row_idx])
                if query_idx >= Int32(0):
                    dim_idx = dim_tile * Int32(8) + dim_local
                    do_val = mGradReadout[query_idx, head_idx, dim_idx]
            sDO[dim_local, row_idx] = do_val
        cute.arch.sync_warp()

        if active:
            tiled_mma = cute.make_tiled_mma(
                warp.MmaF16BF16Op(mGradReadout.element_type, Float32, (16, 8, 16)),
                (1, 1, 1),
                permutation_mnk=(16, 8, 16),
            )
            thr_mma = tiled_mma.get_slice(lane)
            smem_copy_atom = cute.make_copy_atom(
                warp.LdMatrix8x8x16bOp(transpose=False, num_matrices=4),
                mGradReadout.element_type,
            )
            smem_thr_copy_attn = cute_utils.make_tiled_copy_A(smem_copy_atom, tiled_mma).get_slice(lane)
            smem_thr_copy_do = cute_utils.make_tiled_copy_B(smem_copy_atom, tiled_mma).get_slice(lane)
            tSrAttn = cute_utils.mma_make_fragment_A(sAttnT, thr_mma)
            tSrDO = cute_utils.mma_make_fragment_B(sDO, thr_mma)
            tSsAttn = smem_thr_copy_attn.partition_S(sAttnT)
            tSsDO = smem_thr_copy_do.partition_S(sDO)
            acc_shape = thr_mma.partition_shape_C((16, 8))
            c_tile = cute.make_identity_tensor((16, 8))
            tCc = layout_utils.reshape_acc_to_mn(thr_mma.partition_C(c_tile))
            acc = cute.make_fragment(acc_shape, Float32)
            acc.fill(0.0)
            sm80_utils.gemm(
                thr_mma,
                acc,
                tSrAttn,
                tSrDO,
                tSsAttn,
                tSsDO,
                smem_thr_copy_attn,
                smem_thr_copy_do,
            )
            acc_mn = layout_utils.reshape_acc_to_mn(acc)
            for mi in cutlass.range_constexpr(cute.size(tCc.shape[0])):
                for ni in cutlass.range_constexpr(cute.size(tCc.shape[1])):
                    value_slot = tCc[mi, ni][0]
                    dim_local = tCc[mi, ni][1]
                    if value_slot < Int32(self.max_values):
                        sGradValue[value_slot, dim_local] = acc_mn[mi, ni]
        cute.arch.sync_warp()

        if active:
            for elem_idx in cutlass.range(lane, Int32(self.max_values) * Int32(2), cute.arch.WARP_SIZE, unroll=1):
                value_slot = elem_idx // Int32(2)
                dim_group = elem_idx - value_slot * Int32(2)
                value_idx = Int32(mPackValueIndex[pack_idx, value_slot])
                if value_idx >= Int32(0):
                    dim_local0 = dim_group * Int32(4)
                    dim_local1 = dim_local0 + Int32(1)
                    dim_local2 = dim_local0 + Int32(2)
                    dim_local3 = dim_local0 + Int32(3)
                    dim0 = dim_tile * Int32(8) + dim_local0
                    copy_utils.atomic_add_fp32x4(
                        Float32(sGradValue[value_slot, dim_local0]),
                        Float32(sGradValue[value_slot, dim_local1]),
                        Float32(sGradValue[value_slot, dim_local2]),
                        Float32(sGradValue[value_slot, dim_local3]),
                        cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
                    )


class ARHSALeafReadoutBackwardFusedQueryWarpD64Sm100:
    """Fused D=64 query/head readout backward without global stats intermediates."""

    arch = 100

    def __init__(self, *, num_threads: int = 64, denom_precomputed: bool = False):
        self.num_threads = num_threads
        self.warps_per_cta = num_threads // 32
        self.denom_precomputed = denom_precomputed

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mDenom: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.warps_per_cta * 2)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mLeafValueIndex,
            mQueryLeafRowPtr,
            mQueryLeafEntryIndex,
            mDenom,
            mValue,
            mGradReadout,
            mGradP,
            mGradValue,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mDenom: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        warp_idx = tidx // cute.arch.WARP_SIZE
        lane = tidx % cute.arch.WARP_SIZE
        half_warp = lane // Int32(16)
        lane16 = lane - half_warp * Int32(16)
        task_idx = block_idx * Int32(self.warps_per_cta * 2) + warp_idx * Int32(2) + half_warp
        if task_idx < total_tasks:
            num_heads = Int32(mP.shape[1])
            query_idx = task_idx // num_heads
            head_idx = task_idx - query_idx * num_heads
            start = Int32(mQueryLeafRowPtr[query_idx])
            end = Int32(mQueryLeafRowPtr[query_idx + 1])
            leaf_count = end - start

            if cutlass.const_expr(self.denom_precomputed):
                denom = Float32(mDenom[query_idx, head_idx])
            else:
                denom_partial = Float32.zero
                for leaf_offset in cutlass.range(lane16, leaf_count, Int32(16), unroll=1):
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_offset])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    denom_partial += Float32(mP[node_idx, head_idx])
                denom = cute_utils.warp_reduce(denom_partial, lambda a, b: a + b, width=16)
            if denom < Float32(1.0e-8):
                denom = Float32(1.0e-8)
            inv_denom = Float32(1.0) / denom

            dim0 = lane16 * Int32(4)
            dim1 = dim0 + Int32(1)
            dim2 = dim0 + Int32(2)
            dim3 = dim0 + Int32(3)
            d0 = Float32(mGradReadout[query_idx, head_idx, dim0])
            d1 = Float32(mGradReadout[query_idx, head_idx, dim1])
            d2 = Float32(mGradReadout[query_idx, head_idx, dim2])
            d3 = Float32(mGradReadout[query_idx, head_idx, dim3])

            weighted_grad_sum = Float32.zero
            for ptr in cutlass.range(start, end, unroll=1):
                leaf_entry = Int32(mQueryLeafEntryIndex[ptr])
                value_idx = Int32(mLeafValueIndex[leaf_entry])
                partial = d0 * Float32(mValue[value_idx, head_idx, dim0])
                partial += d1 * Float32(mValue[value_idx, head_idx, dim1])
                partial += d2 * Float32(mValue[value_idx, head_idx, dim2])
                partial += d3 * Float32(mValue[value_idx, head_idx, dim3])
                grad_attn = cute_utils.warp_reduce(partial, lambda a, b: a + b, width=16)
                if lane16 == Int32(0):
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    mass = Float32(mP[node_idx, head_idx])
                    weighted_grad_sum += mass * grad_attn

            weighted_grad_mean = weighted_grad_sum * inv_denom
            for ptr in cutlass.range(start, end, unroll=1):
                leaf_entry = Int32(mQueryLeafEntryIndex[ptr])
                node_idx = Int32(mLeafNodeIndex[leaf_entry])
                value_idx = Int32(mLeafValueIndex[leaf_entry])
                mass = Float32(mP[node_idx, head_idx])
                partial = d0 * Float32(mValue[value_idx, head_idx, dim0])
                partial += d1 * Float32(mValue[value_idx, head_idx, dim1])
                partial += d2 * Float32(mValue[value_idx, head_idx, dim2])
                partial += d3 * Float32(mValue[value_idx, head_idx, dim3])
                grad_attn = cute_utils.warp_reduce(partial, lambda a, b: a + b, width=16)
                if lane16 == Int32(0):
                    grad_mass = (grad_attn - weighted_grad_mean) * inv_denom
                    cute_utils.atomic_add_fp32(
                        grad_mass,
                        cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
                    )

                attn = mass * inv_denom
                copy_utils.atomic_add_fp32x4(
                    attn * d0,
                    attn * d1,
                    attn * d2,
                    attn * d3,
                    cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
                )


class ARHSALeafReadoutBackwardFusedSmallSm100:
    """Single-kernel readout backward for small bounded query leaf fanout."""

    arch = 100

    def __init__(
        self,
        *,
        max_leaves_per_query: int,
        num_threads: int = 256,
        vectorize_dim4: bool = False,
    ):
        self.max_leaves_per_query = max_leaves_per_query
        self.num_threads = num_threads
        self.vectorize_dim4 = vectorize_dim4

    @cute.jit
    def __call__(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.num_threads)
        self.kernel(
            mP,
            mLeafNodeIndex,
            mLeafValueIndex,
            mQueryLeafRowPtr,
            mQueryLeafEntryIndex,
            mValue,
            mGradReadout,
            mGradP,
            mGradValue,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mP: cute.Tensor,
        mLeafNodeIndex: cute.Tensor,
        mLeafValueIndex: cute.Tensor,
        mQueryLeafRowPtr: cute.Tensor,
        mQueryLeafEntryIndex: cute.Tensor,
        mValue: cute.Tensor,
        mGradReadout: cute.Tensor,
        mGradP: cute.Tensor,
        mGradValue: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        task_idx = block_idx * self.num_threads + tidx
        if task_idx < total_tasks:
            num_heads = Int32(mP.shape[1])
            head_dim_v = Int32(mValue.shape[2])
            query_idx = task_idx // num_heads
            head_idx = task_idx - query_idx * num_heads
            start = Int32(mQueryLeafRowPtr[query_idx])
            end = Int32(mQueryLeafRowPtr[query_idx + 1])
            leaf_count = end - start

            denom = Float32.zero
            weighted_grad_sum = Float32.zero
            grad_leaf_attn = [Float32.zero for _ in range(self.max_leaves_per_query)]
            for leaf_offset in cutlass.range_constexpr(self.max_leaves_per_query):
                if leaf_offset < leaf_count:
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_offset])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    mass = Float32(mP[node_idx, head_idx])
                    grad_attn = Float32.zero
                    for dim_idx in cutlass.range(head_dim_v, unroll=16):
                        grad_attn += Float32(mGradReadout[query_idx, head_idx, dim_idx]) * Float32(
                            mValue[value_idx, head_idx, dim_idx]
                        )
                    grad_leaf_attn[leaf_offset] = grad_attn
                    denom += mass
                    weighted_grad_sum += mass * grad_attn
            if denom < Float32(1.0e-8):
                denom = Float32(1.0e-8)

            for leaf_offset in cutlass.range_constexpr(self.max_leaves_per_query):
                if leaf_offset < leaf_count:
                    leaf_entry = Int32(mQueryLeafEntryIndex[start + leaf_offset])
                    node_idx = Int32(mLeafNodeIndex[leaf_entry])
                    value_idx = Int32(mLeafValueIndex[leaf_entry])
                    grad_mass = (grad_leaf_attn[leaf_offset] - weighted_grad_sum / denom) / denom
                    cute_utils.atomic_add_fp32(
                        grad_mass,
                        cute_utils.elem_pointer(mGradP, (node_idx, head_idx)),
                    )
                    attn = Float32(mP[node_idx, head_idx]) / denom
                    if cutlass.const_expr(self.vectorize_dim4):
                        for dim_group in cutlass.range(head_dim_v // Int32(4), unroll=4):
                            dim0 = dim_group * Int32(4)
                            dim1 = dim0 + Int32(1)
                            dim2 = dim0 + Int32(2)
                            dim3 = dim0 + Int32(3)
                            copy_utils.atomic_add_fp32x4(
                                attn * Float32(mGradReadout[query_idx, head_idx, dim0]),
                                attn * Float32(mGradReadout[query_idx, head_idx, dim1]),
                                attn * Float32(mGradReadout[query_idx, head_idx, dim2]),
                                attn * Float32(mGradReadout[query_idx, head_idx, dim3]),
                                cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim0)),
                            )
                    else:
                        for dim_idx in cutlass.range(head_dim_v, unroll=16):
                            cute_utils.atomic_add_fp32(
                                attn * Float32(mGradReadout[query_idx, head_idx, dim_idx]),
                                cute_utils.elem_pointer(mGradValue, (value_idx, head_idx, dim_idx)),
                            )


class ARHSAMarkovBackwardStepSm100:
    """One reverse Markov step using source-side outgoing-edge reduction."""

    arch = 100

    def __init__(self, *, num_threads: int = 64, accumulate_grad_edge_prob: bool = True):
        self.num_threads = num_threads
        self.accumulate_grad_edge_prob = accumulate_grad_edge_prob

    @cute.jit
    def __call__(
        self,
        mGradPNext: cute.Tensor,
        mPPrev: cute.Tensor,
        mEdgeProb: cute.Tensor,
        mSrcRowPtr: cute.Tensor,
        mSrcEdgeIndex: cute.Tensor,
        mDst: cute.Tensor,
        mNodeIsSink: cute.Tensor,
        mGradEdgeProb: cute.Tensor,
        mGradPPrev: cute.Tensor,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.num_threads)
        self.kernel(
            mGradPNext,
            mPPrev,
            mEdgeProb,
            mSrcRowPtr,
            mSrcEdgeIndex,
            mDst,
            mNodeIsSink,
            mGradEdgeProb,
            mGradPPrev,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mGradPNext: cute.Tensor,
        mPPrev: cute.Tensor,
        mEdgeProb: cute.Tensor,
        mSrcRowPtr: cute.Tensor,
        mSrcEdgeIndex: cute.Tensor,
        mDst: cute.Tensor,
        mNodeIsSink: cute.Tensor,
        mGradEdgeProb: cute.Tensor,
        mGradPPrev: cute.Tensor,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        task_idx = block_idx * self.num_threads + tidx
        if task_idx < total_tasks:
            num_heads = Int32(mGradPNext.shape[1])
            src_idx = task_idx // num_heads
            head_idx = task_idx - src_idx * num_heads
            acc = Float32.zero
            if mNodeIsSink[src_idx]:
                acc = Float32(mGradPNext[src_idx, head_idx])
            start = Int32(mSrcRowPtr[src_idx])
            end = Int32(mSrcRowPtr[src_idx + 1])
            p_prev = Float32(mPPrev[src_idx, head_idx])
            for ptr in cutlass.range(start, end, unroll=1):
                edge_idx = Int32(mSrcEdgeIndex[ptr])
                dst_idx = Int32(mDst[edge_idx])
                grad_next = Float32(mGradPNext[dst_idx, head_idx])
                acc += grad_next * Float32(mEdgeProb[edge_idx, head_idx])
                grad_edge_prob = p_prev * grad_next
                if cutlass.const_expr(self.accumulate_grad_edge_prob):
                    grad_edge_prob += Float32(mGradEdgeProb[edge_idx, head_idx])
                mGradEdgeProb[edge_idx, head_idx] = grad_edge_prob.to(mGradEdgeProb.element_type)
            mGradPPrev[src_idx, head_idx] = acc.to(mGradPPrev.element_type)


class ARHSAMarkovBackwardRangeStepSm100:
    """Reverse Markov step over a contiguous source-node range."""

    arch = 100

    def __init__(self, *, num_threads: int = 64, accumulate_grad_edge_prob: bool = True):
        self.num_threads = num_threads
        self.accumulate_grad_edge_prob = accumulate_grad_edge_prob

    @cute.jit
    def __call__(
        self,
        mGradPNext: cute.Tensor,
        mPPrev: cute.Tensor,
        mEdgeProb: cute.Tensor,
        mSrcRowPtr: cute.Tensor,
        mSrcEdgeIndex: cute.Tensor,
        mDst: cute.Tensor,
        mNodeIsSink: cute.Tensor,
        mGradEdgeProb: cute.Tensor,
        mGradPPrev: cute.Tensor,
        node_offset: Int32,
        total_tasks: Int32,
        stream: cuda.CUstream,
    ):
        grid_x = cute.ceil_div(total_tasks, self.num_threads)
        self.kernel(
            mGradPNext,
            mPPrev,
            mEdgeProb,
            mSrcRowPtr,
            mSrcEdgeIndex,
            mDst,
            mNodeIsSink,
            mGradEdgeProb,
            mGradPPrev,
            node_offset,
            total_tasks,
        ).launch(
            grid=[grid_x, 1, 1],
            block=[self.num_threads, 1, 1],
            stream=stream,
        )

    @cute.kernel
    def kernel(
        self,
        mGradPNext: cute.Tensor,
        mPPrev: cute.Tensor,
        mEdgeProb: cute.Tensor,
        mSrcRowPtr: cute.Tensor,
        mSrcEdgeIndex: cute.Tensor,
        mDst: cute.Tensor,
        mNodeIsSink: cute.Tensor,
        mGradEdgeProb: cute.Tensor,
        mGradPPrev: cute.Tensor,
        node_offset: Int32,
        total_tasks: Int32,
    ):
        tidx, _, _ = cute.arch.thread_idx()
        block_idx, _, _ = cute.arch.block_idx()
        task_idx = block_idx * self.num_threads + tidx
        if task_idx < total_tasks:
            num_heads = Int32(mGradPNext.shape[1])
            local_src_idx = task_idx // num_heads
            src_idx = node_offset + local_src_idx
            head_idx = task_idx - local_src_idx * num_heads
            acc = Float32.zero
            if mNodeIsSink[src_idx]:
                acc = Float32(mGradPNext[src_idx, head_idx])
            start = Int32(mSrcRowPtr[src_idx])
            end = Int32(mSrcRowPtr[src_idx + 1])
            p_prev = Float32(mPPrev[src_idx, head_idx])
            for ptr in cutlass.range(start, end, unroll=1):
                edge_idx = Int32(mSrcEdgeIndex[ptr])
                dst_idx = Int32(mDst[edge_idx])
                grad_next = Float32(mGradPNext[dst_idx, head_idx])
                acc += grad_next * Float32(mEdgeProb[edge_idx, head_idx])
                grad_edge_prob = p_prev * grad_next
                if cutlass.const_expr(self.accumulate_grad_edge_prob):
                    grad_edge_prob += Float32(mGradEdgeProb[edge_idx, head_idx])
                mGradEdgeProb[edge_idx, head_idx] = grad_edge_prob.to(mGradEdgeProb.element_type)
            mGradPPrev[src_idx, head_idx] = acc.to(mGradPPrev.element_type)


def run_arhsa_markov_incoming_step(
    p: torch.Tensor,
    edge_prob: torch.Tensor,
    src: torch.Tensor,
    dst_row_ptr: torch.Tensor,
    dst_edge_index: torch.Tensor,
    node_is_sink: torch.Tensor,
    p_next: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run one Markov step using the CuTe incoming-edge reduction kernel."""
    _require_cute_runtime()
    if p.device.type != "cuda":
        raise ValueError("p must be a CUDA tensor")
    if p.ndim != 2:
        raise ValueError(f"p must have shape [n_nodes, n_heads], got {tuple(p.shape)}")
    if edge_prob.ndim != 2 or edge_prob.shape[1] != p.shape[1]:
        raise ValueError(
            "edge_prob must have shape [n_edges, n_heads] with matching head count, "
            f"got {tuple(edge_prob.shape)} for p={tuple(p.shape)}"
        )
    if p_next is None:
        p_next = torch.empty_like(p)
    if p_next.shape != p.shape:
        raise ValueError(f"p_next shape mismatch: {tuple(p_next.shape)} vs {tuple(p.shape)}")

    src = src.to(device=p.device, dtype=torch.int32).contiguous()
    dst_row_ptr = dst_row_ptr.to(device=p.device, dtype=torch.int32).contiguous()
    dst_edge_index = dst_edge_index.to(device=p.device, dtype=torch.int32).contiguous()
    node_is_sink = node_is_sink.to(device=p.device, dtype=torch.bool).contiguous()
    edge_prob = edge_prob.contiguous()
    p = p.contiguous()

    total_tasks = int(p.shape[0] * p.shape[1])
    if total_tasks == 0:
        return p_next

    compile_key = (
        "arhsa_markov_incoming_step",
        p.dtype,
        edge_prob.dtype,
        p.shape[1],
        torch.cuda.get_device_capability(p.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_markov_incoming_step.compile_cache:
        op = ARHSAMarkovIncomingStepSm100()
        run_arhsa_markov_incoming_step.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(p),
            to_cute_tensor(edge_prob),
            to_cute_tensor(src, assumed_align=4),
            to_cute_tensor(dst_row_ptr, assumed_align=4),
            to_cute_tensor(dst_edge_index, assumed_align=4),
            to_cute_tensor(node_is_sink),
            to_cute_tensor(p_next),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_markov_incoming_step.compile_cache[compile_key](
        p,
        edge_prob,
        src,
        dst_row_ptr,
        dst_edge_index,
        node_is_sink,
        p_next,
        Int32(total_tasks),
        current_stream,
    )
    return p_next


def run_arhsa_gather_edge_prob_by_index(
    edge_prob: torch.Tensor,
    edge_index: torch.Tensor,
    gathered_edge_prob: torch.Tensor | None = None,
) -> torch.Tensor:
    """Gather ``edge_prob[edge_index]`` with a small CuTe copy kernel."""
    _require_cute_runtime()
    if edge_prob.device.type != "cuda":
        raise ValueError("edge_prob must be a CUDA tensor")
    if edge_prob.ndim != 2:
        raise ValueError(f"edge_prob must have shape [n_edges, n_heads], got {tuple(edge_prob.shape)}")
    if edge_index.ndim != 1:
        raise ValueError(f"edge_index must be 1D, got {tuple(edge_index.shape)}")
    if gathered_edge_prob is None:
        gathered_edge_prob = torch.empty((edge_index.numel(), edge_prob.shape[1]), dtype=edge_prob.dtype, device=edge_prob.device)
    if gathered_edge_prob.shape != (edge_index.numel(), edge_prob.shape[1]):
        raise ValueError(
            f"gathered_edge_prob shape mismatch: got {tuple(gathered_edge_prob.shape)}, "
            f"expected {(edge_index.numel(), edge_prob.shape[1])}"
        )
    edge_prob = edge_prob.contiguous()
    edge_index = edge_index.to(device=edge_prob.device, dtype=torch.int32).contiguous()
    gathered_edge_prob = gathered_edge_prob.contiguous()
    total_tasks = int(edge_index.numel() * edge_prob.shape[1])
    if total_tasks == 0:
        return gathered_edge_prob

    compile_key = (
        "arhsa_gather_edge_prob_by_index",
        edge_prob.dtype,
        edge_prob.shape[1],
        torch.cuda.get_device_capability(edge_prob.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_gather_edge_prob_by_index.compile_cache:
        op = ARHSAGatherEdgeProbByIndexSm100()
        run_arhsa_gather_edge_prob_by_index.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(edge_prob),
            to_cute_tensor(edge_index, assumed_align=4),
            to_cute_tensor(gathered_edge_prob),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_gather_edge_prob_by_index.compile_cache[compile_key](
        edge_prob,
        edge_index,
        gathered_edge_prob,
        Int32(total_tasks),
        current_stream,
    )
    return gathered_edge_prob


def run_arhsa_markov_incoming_packed_step(
    p: torch.Tensor,
    incoming_edge_prob: torch.Tensor,
    incoming_src: torch.Tensor,
    dst_row_ptr: torch.Tensor,
    node_is_sink: torch.Tensor,
    p_next: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run one Markov step with edge metadata already packed in incoming-CSR order."""
    _require_cute_runtime()
    if p.device.type != "cuda":
        raise ValueError("p must be a CUDA tensor")
    if p.ndim != 2:
        raise ValueError(f"p must have shape [n_nodes, n_heads], got {tuple(p.shape)}")
    if incoming_edge_prob.ndim != 2 or incoming_edge_prob.shape[1] != p.shape[1]:
        raise ValueError("incoming_edge_prob must have shape [n_edges, n_heads] with matching head count")
    if incoming_src.ndim != 1 or incoming_src.shape[0] != incoming_edge_prob.shape[0]:
        raise ValueError("incoming_src must have shape [n_edges]")
    if p_next is None:
        p_next = torch.empty_like(p)
    if p_next.shape != p.shape:
        raise ValueError(f"p_next shape mismatch: {tuple(p_next.shape)} vs {tuple(p.shape)}")

    p = p.contiguous()
    incoming_edge_prob = incoming_edge_prob.contiguous()
    incoming_src = incoming_src.to(device=p.device, dtype=torch.int32).contiguous()
    dst_row_ptr = dst_row_ptr.to(device=p.device, dtype=torch.int32).contiguous()
    node_is_sink = node_is_sink.to(device=p.device, dtype=torch.bool).contiguous()
    total_tasks = int(p.shape[0] * p.shape[1])
    if total_tasks == 0:
        return p_next

    compile_key = (
        "arhsa_markov_incoming_packed_step",
        p.dtype,
        incoming_edge_prob.dtype,
        p.shape[1],
        torch.cuda.get_device_capability(p.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_markov_incoming_packed_step.compile_cache:
        op = ARHSAMarkovIncomingPackedStepSm100()
        run_arhsa_markov_incoming_packed_step.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(p),
            to_cute_tensor(incoming_edge_prob),
            to_cute_tensor(incoming_src, assumed_align=4),
            to_cute_tensor(dst_row_ptr, assumed_align=4),
            to_cute_tensor(node_is_sink),
            to_cute_tensor(p_next),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_markov_incoming_packed_step.compile_cache[compile_key](
        p,
        incoming_edge_prob,
        incoming_src,
        dst_row_ptr,
        node_is_sink,
        p_next,
        Int32(total_tasks),
        current_stream,
    )
    return p_next


def run_arhsa_markov_incoming_packed_range_step(
    p: torch.Tensor,
    incoming_edge_prob: torch.Tensor,
    incoming_src: torch.Tensor,
    dst_row_ptr: torch.Tensor,
    node_is_sink: torch.Tensor,
    *,
    node_start: int,
    node_count: int,
    carry_sinks: bool = True,
    p_next: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run one packed Markov step over a contiguous destination-node range."""
    _require_cute_runtime()
    if p.device.type != "cuda":
        raise ValueError("p must be a CUDA tensor")
    if p.ndim != 2:
        raise ValueError(f"p must have shape [n_nodes, n_heads], got {tuple(p.shape)}")
    if incoming_edge_prob.ndim != 2 or incoming_edge_prob.shape[1] != p.shape[1]:
        raise ValueError("incoming_edge_prob must have shape [n_edges, n_heads] with matching head count")
    if incoming_src.ndim != 1 or incoming_src.shape[0] != incoming_edge_prob.shape[0]:
        raise ValueError("incoming_src must have shape [n_edges]")
    node_start = int(node_start)
    node_count = int(node_count)
    if node_start < 0 or node_count < 0 or node_start + node_count > int(p.shape[0]):
        raise ValueError(
            f"invalid node range start={node_start} count={node_count} for n_nodes={int(p.shape[0])}"
        )
    if p_next is None:
        p_next = torch.empty_like(p)
    if p_next.shape != p.shape:
        raise ValueError(f"p_next shape mismatch: {tuple(p_next.shape)} vs {tuple(p.shape)}")

    p = p.contiguous()
    incoming_edge_prob = incoming_edge_prob.contiguous()
    incoming_src = incoming_src.to(device=p.device, dtype=torch.int32).contiguous()
    dst_row_ptr = dst_row_ptr.to(device=p.device, dtype=torch.int32).contiguous()
    node_is_sink = node_is_sink.to(device=p.device, dtype=torch.bool).contiguous()
    total_tasks = int(node_count * p.shape[1])
    if total_tasks == 0:
        return p_next

    compile_key = (
        "arhsa_markov_incoming_packed_range_step",
        p.dtype,
        incoming_edge_prob.dtype,
        p.shape[1],
        torch.cuda.get_device_capability(p.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_markov_incoming_packed_range_step.compile_cache:
        op = ARHSAMarkovIncomingPackedRangeStepSm100()
        run_arhsa_markov_incoming_packed_range_step.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(p),
            to_cute_tensor(incoming_edge_prob),
            to_cute_tensor(incoming_src, assumed_align=4),
            to_cute_tensor(dst_row_ptr, assumed_align=4),
            to_cute_tensor(node_is_sink),
            to_cute_tensor(p_next),
            Int32(node_start),
            Int32(1 if carry_sinks else 0),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_markov_incoming_packed_range_step.compile_cache[compile_key](
        p,
        incoming_edge_prob,
        incoming_src,
        dst_row_ptr,
        node_is_sink,
        p_next,
        Int32(node_start),
        Int32(1 if carry_sinks else 0),
        Int32(total_tasks),
        current_stream,
    )
    return p_next


def run_arhsa_outgoing_softmax(
    edge_scores: torch.Tensor,
    src_row_ptr: torch.Tensor,
    src_edge_index: torch.Tensor,
    *,
    n_nodes: int,
    edge_prob: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run grouped outgoing-edge softmax using the CuTe source-CSR kernel."""
    _require_cute_runtime()
    if edge_scores.device.type != "cuda":
        raise ValueError("edge_scores must be a CUDA tensor")
    if edge_scores.ndim != 2:
        raise ValueError(f"edge_scores must have shape [n_edges, n_heads], got {tuple(edge_scores.shape)}")
    n_nodes = int(n_nodes)
    if n_nodes < 0:
        raise ValueError("n_nodes must be >= 0")
    if edge_prob is None:
        edge_prob = torch.empty_like(edge_scores)
    if edge_prob.shape != edge_scores.shape:
        raise ValueError(f"edge_prob shape mismatch: {tuple(edge_prob.shape)} vs {tuple(edge_scores.shape)}")

    edge_scores = edge_scores.contiguous()
    edge_prob = edge_prob.contiguous()
    src_row_ptr = src_row_ptr.to(device=edge_scores.device, dtype=torch.int32).contiguous()
    src_edge_index = src_edge_index.to(device=edge_scores.device, dtype=torch.int32).contiguous()
    total_tasks = int(n_nodes * edge_scores.shape[1])
    if total_tasks == 0:
        return edge_prob

    compile_key = (
        "arhsa_outgoing_softmax",
        edge_scores.dtype,
        edge_scores.shape[1],
        torch.cuda.get_device_capability(edge_scores.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_outgoing_softmax.compile_cache:
        op = ARHSAOutgoingSoftmaxSm100()
        run_arhsa_outgoing_softmax.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(edge_scores),
            to_cute_tensor(src_row_ptr, assumed_align=4),
            to_cute_tensor(src_edge_index, assumed_align=4),
            to_cute_tensor(edge_prob),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_outgoing_softmax.compile_cache[compile_key](
        edge_scores,
        src_row_ptr,
        src_edge_index,
        edge_prob,
        Int32(total_tasks),
        current_stream,
    )
    return edge_prob


def run_arhsa_outgoing_softmax_with_incoming(
    edge_scores: torch.Tensor,
    src_row_ptr: torch.Tensor,
    src_edge_index: torch.Tensor,
    edge_incoming_index: torch.Tensor,
    *,
    n_nodes: int,
    edge_prob: torch.Tensor | None = None,
    incoming_edge_prob: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Run outgoing softmax and also write probabilities in incoming-CSR edge order."""
    _require_cute_runtime()
    if edge_scores.device.type != "cuda":
        raise ValueError("edge_scores must be a CUDA tensor")
    if edge_scores.ndim != 2:
        raise ValueError(f"edge_scores must have shape [n_edges, n_heads], got {tuple(edge_scores.shape)}")
    if edge_incoming_index.ndim != 1 or edge_incoming_index.shape[0] != edge_scores.shape[0]:
        raise ValueError("edge_incoming_index must have shape [n_edges]")
    n_nodes = int(n_nodes)
    if n_nodes < 0:
        raise ValueError("n_nodes must be >= 0")
    if edge_prob is None:
        edge_prob = torch.empty_like(edge_scores)
    if incoming_edge_prob is None:
        incoming_edge_prob = torch.empty_like(edge_scores)
    if edge_prob.shape != edge_scores.shape:
        raise ValueError(f"edge_prob shape mismatch: {tuple(edge_prob.shape)} vs {tuple(edge_scores.shape)}")
    if incoming_edge_prob.shape != edge_scores.shape:
        raise ValueError(
            f"incoming_edge_prob shape mismatch: {tuple(incoming_edge_prob.shape)} vs {tuple(edge_scores.shape)}"
        )

    edge_scores = edge_scores.contiguous()
    edge_prob = edge_prob.contiguous()
    incoming_edge_prob = incoming_edge_prob.contiguous()
    src_row_ptr = src_row_ptr.to(device=edge_scores.device, dtype=torch.int32).contiguous()
    src_edge_index = src_edge_index.to(device=edge_scores.device, dtype=torch.int32).contiguous()
    edge_incoming_index = edge_incoming_index.to(device=edge_scores.device, dtype=torch.int32).contiguous()
    total_tasks = int(n_nodes * edge_scores.shape[1])
    if total_tasks == 0:
        return edge_prob, incoming_edge_prob

    compile_key = (
        "arhsa_outgoing_softmax_with_incoming",
        edge_scores.dtype,
        edge_scores.shape[1],
        torch.cuda.get_device_capability(edge_scores.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_outgoing_softmax_with_incoming.compile_cache:
        op = ARHSAOutgoingSoftmaxWithIncomingSm100()
        run_arhsa_outgoing_softmax_with_incoming.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(edge_scores),
            to_cute_tensor(src_row_ptr, assumed_align=4),
            to_cute_tensor(src_edge_index, assumed_align=4),
            to_cute_tensor(edge_incoming_index, assumed_align=4),
            to_cute_tensor(edge_prob),
            to_cute_tensor(incoming_edge_prob),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_outgoing_softmax_with_incoming.compile_cache[compile_key](
        edge_scores,
        src_row_ptr,
        src_edge_index,
        edge_incoming_index,
        edge_prob,
        incoming_edge_prob,
        Int32(total_tasks),
        current_stream,
    )
    return edge_prob, incoming_edge_prob


def run_arhsa_outgoing_softmax_backward(
    edge_prob: torch.Tensor,
    grad_edge_prob: torch.Tensor,
    src_row_ptr: torch.Tensor,
    src_edge_index: torch.Tensor,
    *,
    n_nodes: int,
    grad_edge_scores: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run grouped outgoing softmax backward using the CuTe source-CSR kernel."""
    _require_cute_runtime()
    if edge_prob.device.type != "cuda":
        raise ValueError("edge_prob must be a CUDA tensor")
    if edge_prob.ndim != 2:
        raise ValueError(f"edge_prob must have shape [n_edges, n_heads], got {tuple(edge_prob.shape)}")
    if grad_edge_prob.shape != edge_prob.shape:
        raise ValueError(f"grad_edge_prob shape mismatch: {tuple(grad_edge_prob.shape)} vs {tuple(edge_prob.shape)}")
    n_nodes = int(n_nodes)
    if n_nodes < 0:
        raise ValueError("n_nodes must be >= 0")
    if grad_edge_scores is None:
        grad_edge_scores = torch.empty_like(edge_prob)
    if grad_edge_scores.shape != edge_prob.shape:
        raise ValueError(f"grad_edge_scores shape mismatch: {tuple(grad_edge_scores.shape)} vs {tuple(edge_prob.shape)}")

    edge_prob = edge_prob.contiguous()
    grad_edge_prob = grad_edge_prob.contiguous()
    grad_edge_scores = grad_edge_scores.contiguous()
    src_row_ptr = src_row_ptr.to(device=edge_prob.device, dtype=torch.int32).contiguous()
    src_edge_index = src_edge_index.to(device=edge_prob.device, dtype=torch.int32).contiguous()
    total_tasks = int(n_nodes * edge_prob.shape[1])
    if total_tasks == 0:
        return grad_edge_scores

    compile_key = (
        "arhsa_outgoing_softmax_backward",
        edge_prob.dtype,
        grad_edge_prob.dtype,
        grad_edge_scores.dtype,
        edge_prob.shape[1],
        torch.cuda.get_device_capability(edge_prob.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_outgoing_softmax_backward.compile_cache:
        op = ARHSAOutgoingSoftmaxBackwardSm100()
        run_arhsa_outgoing_softmax_backward.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(edge_prob),
            to_cute_tensor(grad_edge_prob),
            to_cute_tensor(src_row_ptr, assumed_align=4),
            to_cute_tensor(src_edge_index, assumed_align=4),
            to_cute_tensor(grad_edge_scores),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_outgoing_softmax_backward.compile_cache[compile_key](
        edge_prob,
        grad_edge_prob,
        src_row_ptr,
        src_edge_index,
        grad_edge_scores,
        Int32(total_tasks),
        current_stream,
    )
    return grad_edge_scores


def run_arhsa_sampled_node_dot(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    feature_row_level: torch.Tensor,
    query_node_feature_row_index: torch.Tensor,
    query_node_query_index: torch.Tensor,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run fused sampled q[level] dot row_repr for 4-D per-head ARHSAv2 tensors."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4:
        raise ValueError(f"q_levels must have shape [n_queries, n_levels, n_heads, head_dim], got {tuple(q_levels.shape)}")
    if row_repr.ndim != 3:
        raise ValueError(f"row_repr must have shape [n_rows, n_heads, head_dim], got {tuple(row_repr.shape)}")
    if q_levels.shape[2:] != row_repr.shape[1:]:
        raise ValueError("q_levels and row_repr head dimensions must match")
    if q_levels.dtype not in _CUTE_BACKWARD_DTYPES or row_repr.dtype not in _CUTE_BACKWARD_DTYPES:
        raise ValueError(f"q_levels/row_repr dtype must be one of {_CUTE_BACKWARD_DTYPES}")
    if out is None:
        out = torch.empty(
            (query_node_feature_row_index.numel(), row_repr.shape[1]),
            dtype=row_repr.dtype,
            device=row_repr.device,
        )
    if out.shape != (query_node_feature_row_index.numel(), row_repr.shape[1]):
        raise ValueError(f"out shape mismatch: got {tuple(out.shape)}")
    if out.dtype not in _CUTE_BACKWARD_DTYPES:
        raise ValueError(f"out dtype must be one of {_CUTE_BACKWARD_DTYPES}, got {out.dtype}")

    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    out = out.contiguous()
    feature_row_level = feature_row_level.to(device=q_levels.device, dtype=torch.int32).contiguous()
    query_node_feature_row_index = query_node_feature_row_index.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    query_node_query_index = query_node_query_index.to(device=q_levels.device, dtype=torch.int32).contiguous()
    use_head_pair = (
        row_repr.shape[1] == 2
        and os.environ.get("HSA_CUTE_SAMPLED_NODE_DOT_HEAD_PAIR", "1")
        not in {"0", "false", "False", ""}
    )
    total_tasks = int(
        query_node_feature_row_index.numel()
        if use_head_pair
        else query_node_feature_row_index.numel() * row_repr.shape[1]
    )
    if total_tasks == 0:
        return out

    scale = float(q_levels.shape[-1] ** 0.5)
    num_threads = int(os.environ.get("HSA_CUTE_SAMPLED_NODE_DOT_THREADS", "128"))
    if num_threads not in {128, 256, 512}:
        raise ValueError("HSA_CUTE_SAMPLED_NODE_DOT_THREADS must be 128, 256, or 512")
    compile_key = (
        "arhsa_sampled_node_dot_h2" if use_head_pair else "arhsa_sampled_node_dot",
        q_levels.dtype,
        row_repr.dtype,
        out.dtype,
        q_levels.shape[2],
        q_levels.shape[3],
        num_threads,
        torch.cuda.get_device_capability(q_levels.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_sampled_node_dot.compile_cache:
        op = (
            ARHSASampledNodeDotH2Sm100(num_threads=num_threads)
            if use_head_pair
            else ARHSASampledNodeDotSm100(num_threads=num_threads)
        )
        run_arhsa_sampled_node_dot.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(q_levels),
            to_cute_tensor(row_repr),
            to_cute_tensor(feature_row_level, assumed_align=4),
            to_cute_tensor(query_node_feature_row_index, assumed_align=4),
            to_cute_tensor(query_node_query_index, assumed_align=4),
            to_cute_tensor(out),
            Float32(scale),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_sampled_node_dot.compile_cache[compile_key](
        q_levels,
        row_repr,
        feature_row_level,
        query_node_feature_row_index,
        query_node_query_index,
        out,
        Float32(scale),
        Int32(total_tasks),
        current_stream,
    )
    return out


def run_arhsa_sampled_node_dot_backward(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    grad_out: torch.Tensor,
    feature_row_level: torch.Tensor,
    query_node_feature_row_index: torch.Tensor,
    query_node_query_index: torch.Tensor,
    grad_q: torch.Tensor | None = None,
    grad_row: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Run sampled-node-dot backward, accumulating in FP32 for BF16 inputs."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4:
        raise ValueError(f"q_levels must have shape [n_queries, n_levels, n_heads, head_dim], got {tuple(q_levels.shape)}")
    if row_repr.ndim != 3 or row_repr.shape[1:] != q_levels.shape[2:]:
        raise ValueError("row_repr must have shape [n_rows, n_heads, head_dim] matching q_levels")
    if grad_out.shape != (query_node_feature_row_index.numel(), row_repr.shape[1]):
        raise ValueError(f"grad_out shape mismatch: got {tuple(grad_out.shape)}")
    if q_levels.dtype not in _CUTE_BACKWARD_DTYPES or row_repr.dtype not in _CUTE_BACKWARD_DTYPES:
        raise ValueError(f"q_levels/row_repr dtype must be one of {_CUTE_BACKWARD_DTYPES}")
    if grad_out.dtype not in _CUTE_BACKWARD_DTYPES:
        raise ValueError(f"grad_out dtype must be one of {_CUTE_BACKWARD_DTYPES}, got {grad_out.dtype}")

    grad_q_out = grad_q
    grad_row_out = grad_row
    if grad_q is not None and grad_q.shape != q_levels.shape:
        raise ValueError(f"grad_q shape mismatch: got {tuple(grad_q.shape)}")
    if grad_row is not None and grad_row.shape != row_repr.shape:
        raise ValueError(f"grad_row shape mismatch: got {tuple(grad_row.shape)}")
    if q_levels.dtype == torch.float32:
        grad_q = torch.zeros_like(q_levels) if grad_q is None else grad_q.zero_()
    elif grad_q is not None and grad_q.dtype == torch.float32:
        grad_q.zero_()
    else:
        grad_q = torch.zeros_like(q_levels, dtype=torch.float32)
    if row_repr.dtype == torch.float32:
        grad_row = torch.zeros_like(row_repr) if grad_row is None else grad_row.zero_()
    elif grad_row is not None and grad_row.dtype == torch.float32:
        grad_row.zero_()
    else:
        grad_row = torch.zeros_like(row_repr, dtype=torch.float32)

    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    grad_out = grad_out.contiguous()
    feature_row_level = feature_row_level.to(device=q_levels.device, dtype=torch.int32).contiguous()
    query_node_feature_row_index = query_node_feature_row_index.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    query_node_query_index = query_node_query_index.to(device=q_levels.device, dtype=torch.int32).contiguous()
    use_head_pair = (
        row_repr.shape[1] == 2
        and os.environ.get("HSA_CUTE_SAMPLED_NODE_DOT_HEAD_PAIR", "1")
        not in {"0", "false", "False", ""}
    )
    use_head_pair_d64_vec = (
        use_head_pair
        and row_repr.shape[2] == 64
        and os.environ.get("HSA_CUTE_SAMPLED_NODE_DOT_H2_D64_VEC", "1")
        not in {"0", "false", "False", ""}
    )
    use_head_pair_d64_cta_reduce = (
        use_head_pair_d64_vec
        and os.environ.get("HSA_CUTE_SAMPLED_NODE_DOT_H2_D64_CTA_REDUCE", "1")
        not in {"0", "false", "False", ""}
    )
    total_tasks = int(
        query_node_feature_row_index.numel()
        if use_head_pair
        else query_node_feature_row_index.numel() * row_repr.shape[1]
    )
    if total_tasks > 0:
        scale = float(q_levels.shape[-1] ** 0.5)
        num_threads = int(os.environ.get("HSA_CUTE_SAMPLED_NODE_DOT_THREADS", "128"))
        if num_threads not in {128, 256, 512}:
            raise ValueError("HSA_CUTE_SAMPLED_NODE_DOT_THREADS must be 128, 256, or 512")
        compile_key = (
            (
                "arhsa_sampled_node_dot_backward_h2_d64_vec"
                if use_head_pair_d64_vec
                else (
                    "arhsa_sampled_node_dot_backward_h2"
                    if use_head_pair
                    else "arhsa_sampled_node_dot_backward"
                )
            ),
            q_levels.dtype,
            row_repr.dtype,
            grad_out.dtype,
            grad_q.dtype,
            grad_row.dtype,
            q_levels.shape[2],
            q_levels.shape[3],
            num_threads,
            use_head_pair_d64_cta_reduce,
            torch.cuda.get_device_capability(q_levels.device),
        )
        current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
        if compile_key not in run_arhsa_sampled_node_dot_backward.compile_cache:
            op = (
                ARHSASampledNodeDotBackwardH2D64VecSm100(
                    num_threads=num_threads,
                    cta_reduce_grad_q=use_head_pair_d64_cta_reduce,
                )
                if use_head_pair_d64_vec
                else (
                    ARHSASampledNodeDotBackwardH2Sm100(num_threads=num_threads)
                    if use_head_pair
                    else ARHSASampledNodeDotBackwardSm100(num_threads=num_threads)
                )
            )
            run_arhsa_sampled_node_dot_backward.compile_cache[compile_key] = cute.compile(
                op,
                to_cute_tensor(q_levels),
                to_cute_tensor(row_repr),
                to_cute_tensor(grad_out),
                to_cute_tensor(feature_row_level, assumed_align=4),
                to_cute_tensor(query_node_feature_row_index, assumed_align=4),
                to_cute_tensor(query_node_query_index, assumed_align=4),
                to_cute_tensor(grad_q),
                to_cute_tensor(grad_row),
                Float32(scale),
                Int32(total_tasks),
                current_stream,
                options="--enable-tvm-ffi",
            )
        run_arhsa_sampled_node_dot_backward.compile_cache[compile_key](
            q_levels,
            row_repr,
            grad_out,
            feature_row_level,
            query_node_feature_row_index,
            query_node_query_index,
            grad_q,
            grad_row,
            Float32(scale),
            Int32(total_tasks),
            current_stream,
        )

    if grad_q_out is not None and grad_q_out.data_ptr() != grad_q.data_ptr():
        grad_q_out.copy_(grad_q.to(dtype=grad_q_out.dtype))
        grad_q = grad_q_out
    elif grad_q_out is None and grad_q.dtype != q_levels.dtype:
        grad_q = grad_q.to(dtype=q_levels.dtype)
    if grad_row_out is not None and grad_row_out.data_ptr() != grad_row.data_ptr():
        grad_row_out.copy_(grad_row.to(dtype=grad_row_out.dtype))
        grad_row = grad_row_out
    elif grad_row_out is None and grad_row.dtype != row_repr.dtype:
        grad_row = grad_row.to(dtype=row_repr.dtype)
    return grad_q, grad_row


def run_arhsa_v3_start_score_forward(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    start_feature_rows: torch.Tensor,
    start_query_index: torch.Tensor,
    start_levels: torch.Tensor,
    down_bias: torch.Tensor,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run packed-v3 two-head start-score dot plus bias in one CuTe kernel."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4:
        raise ValueError(f"q_levels must have shape [n_queries, n_levels, n_heads, head_dim], got {tuple(q_levels.shape)}")
    if row_repr.ndim != 3 or row_repr.shape[1:] != q_levels.shape[2:]:
        raise ValueError("row_repr must have shape [n_rows, n_heads, head_dim] matching q_levels")
    if int(row_repr.shape[1]) != 2:
        raise ValueError("run_arhsa_v3_start_score_forward currently requires exactly two heads")
    n_starts = int(start_feature_rows.numel())
    if start_query_index.shape != (n_starts,) or start_levels.shape != (n_starts,):
        raise ValueError("start_feature_rows, start_query_index, and start_levels must have matching 1D shapes")
    if down_bias.reshape(-1).numel() not in {1, 2}:
        raise ValueError("down_bias must be scalar or length two")
    if q_levels.dtype not in _CUTE_BACKWARD_DTYPES or row_repr.dtype not in _CUTE_BACKWARD_DTYPES:
        raise ValueError(f"q_levels/row_repr dtype must be one of {_CUTE_BACKWARD_DTYPES}")
    if out is None:
        out = torch.empty(
            (n_starts, row_repr.shape[1]),
            dtype=torch.promote_types(row_repr.dtype, down_bias.dtype),
            device=row_repr.device,
        )
    if out.shape != (n_starts, row_repr.shape[1]):
        raise ValueError(f"out shape mismatch: got {tuple(out.shape)}")
    if out.dtype not in _CUTE_BACKWARD_DTYPES:
        raise ValueError(f"out dtype must be one of {_CUTE_BACKWARD_DTYPES}, got {out.dtype}")

    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    start_feature_rows = start_feature_rows.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    start_query_index = start_query_index.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    start_levels = start_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    down_bias = down_bias.reshape(-1).to(device=q_levels.device).contiguous()
    out = out.contiguous()
    total_tasks = int(start_feature_rows.numel())
    if total_tasks == 0:
        return out

    scale = float(q_levels.shape[-1] ** 0.5)
    num_threads = int(os.environ.get("HSA_CUTE_V3_START_SCORE_THREADS", "256"))
    if num_threads not in {128, 256, 512}:
        raise ValueError("HSA_CUTE_V3_START_SCORE_THREADS must be 128, 256, or 512")
    compile_key = (
        "arhsa_v3_start_score_h2",
        q_levels.dtype,
        row_repr.dtype,
        down_bias.dtype,
        out.dtype,
        q_levels.shape[2],
        q_levels.shape[3],
        down_bias.numel(),
        num_threads,
        torch.cuda.get_device_capability(q_levels.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_v3_start_score_forward.compile_cache:
        op = ARHSAV3StartScoreH2Sm100(num_threads=num_threads)
        run_arhsa_v3_start_score_forward.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(q_levels),
            to_cute_tensor(row_repr),
            to_cute_tensor(start_feature_rows, assumed_align=4),
            to_cute_tensor(start_query_index, assumed_align=4),
            to_cute_tensor(start_levels, assumed_align=4),
            to_cute_tensor(down_bias),
            to_cute_tensor(out),
            Float32(scale),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_v3_start_score_forward.compile_cache[compile_key](
        q_levels,
        row_repr,
        start_feature_rows,
        start_query_index,
        start_levels,
        down_bias,
        out,
        Float32(scale),
        Int32(total_tasks),
        current_stream,
    )
    return out


def run_arhsa_v3_start_score_backward_segmented(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    grad_out: torch.Tensor,
    start_feature_rows: torch.Tensor,
    start_query_index: torch.Tensor,
    start_levels: torch.Tensor,
    start_level_begin: torch.Tensor,
    start_level_end: torch.Tensor,
    grad_q: torch.Tensor | None = None,
    grad_row: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Run packed-v3 start-score backward with segmented grad-q reduction."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4:
        raise ValueError(f"q_levels must have shape [n_queries, n_levels, n_heads, head_dim], got {tuple(q_levels.shape)}")
    if row_repr.ndim != 3 or row_repr.shape[1:] != q_levels.shape[2:]:
        raise ValueError("row_repr must have shape [n_rows, n_heads, head_dim] matching q_levels")
    if row_repr.shape[1] != 2:
        raise ValueError("segmented v3 start-score backward currently requires exactly two heads")
    if grad_out.shape != (start_feature_rows.numel(), row_repr.shape[1]):
        raise ValueError(f"grad_out shape mismatch: got {tuple(grad_out.shape)}")
    qlevel_tasks = int(q_levels.shape[0] * q_levels.shape[1])
    if start_level_begin.shape != (qlevel_tasks,) or start_level_end.shape != (qlevel_tasks,):
        raise ValueError(
            "start_level_begin/end must have shape [n_queries * n_levels], "
            f"got {tuple(start_level_begin.shape)} / {tuple(start_level_end.shape)}"
        )
    if q_levels.dtype not in _CUTE_BACKWARD_DTYPES or row_repr.dtype not in _CUTE_BACKWARD_DTYPES:
        raise ValueError(f"q_levels/row_repr dtype must be one of {_CUTE_BACKWARD_DTYPES}")
    if grad_out.dtype not in _CUTE_BACKWARD_DTYPES:
        raise ValueError(f"grad_out dtype must be one of {_CUTE_BACKWARD_DTYPES}, got {grad_out.dtype}")

    grad_q_out = grad_q
    grad_row_out = grad_row
    if grad_q is not None and grad_q.shape != q_levels.shape:
        raise ValueError(f"grad_q shape mismatch: got {tuple(grad_q.shape)}")
    if grad_row is not None and grad_row.shape != row_repr.shape:
        raise ValueError(f"grad_row shape mismatch: got {tuple(grad_row.shape)}")
    if q_levels.dtype == torch.float32:
        grad_q = torch.empty_like(q_levels) if grad_q is None else grad_q
    elif grad_q is not None and grad_q.dtype == torch.float32:
        pass
    else:
        grad_q = torch.empty_like(q_levels, dtype=torch.float32)
    if row_repr.dtype == torch.float32:
        grad_row = torch.zeros_like(row_repr) if grad_row is None else grad_row.zero_()
    elif grad_row is not None and grad_row.dtype == torch.float32:
        grad_row.zero_()
    else:
        grad_row = torch.zeros_like(row_repr, dtype=torch.float32)

    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    grad_out = grad_out.contiguous()
    start_feature_rows = start_feature_rows.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    start_query_index = start_query_index.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    start_levels = start_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    start_level_begin = start_level_begin.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    start_level_end = start_level_end.to(device=q_levels.device, dtype=torch.int32).contiguous()
    grad_q = grad_q.contiguous()
    grad_row = grad_row.contiguous()

    scale = float(q_levels.shape[-1] ** 0.5)
    num_threads = int(os.environ.get("HSA_CUTE_V3_START_SCORE_SEG_THREADS", "128"))
    if num_threads not in {128, 256, 512}:
        raise ValueError("HSA_CUTE_V3_START_SCORE_SEG_THREADS must be 128, 256, or 512")
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)

    row_tasks = int(start_feature_rows.numel())
    if row_tasks > 0:
        row_key = (
            "arhsa_v3_start_score_grad_row_only_h2",
            q_levels.dtype,
            grad_out.dtype,
            grad_row.dtype,
            q_levels.shape[2],
            q_levels.shape[3],
            num_threads,
            torch.cuda.get_device_capability(q_levels.device),
        )
        if row_key not in run_arhsa_v3_start_score_backward_segmented.compile_cache:
            row_op = ARHSAV3StartScoreGradRowOnlyH2Sm100(num_threads=num_threads)
            run_arhsa_v3_start_score_backward_segmented.compile_cache[row_key] = cute.compile(
                row_op,
                to_cute_tensor(q_levels),
                to_cute_tensor(grad_out),
                to_cute_tensor(start_feature_rows, assumed_align=4),
                to_cute_tensor(start_query_index, assumed_align=4),
                to_cute_tensor(start_levels, assumed_align=4),
                to_cute_tensor(grad_row),
                Float32(scale),
                Int32(row_tasks),
                current_stream,
                options="--enable-tvm-ffi",
            )
        run_arhsa_v3_start_score_backward_segmented.compile_cache[row_key](
            q_levels,
            grad_out,
            start_feature_rows,
            start_query_index,
            start_levels,
            grad_row,
            Float32(scale),
            Int32(row_tasks),
            current_stream,
        )

    if qlevel_tasks > 0:
        q_key = (
            "arhsa_v3_start_score_grad_q_segment_h2",
            row_repr.dtype,
            grad_out.dtype,
            grad_q.dtype,
            q_levels.shape[1],
            q_levels.shape[2],
            q_levels.shape[3],
            num_threads,
            torch.cuda.get_device_capability(q_levels.device),
        )
        if q_key not in run_arhsa_v3_start_score_backward_segmented.compile_cache:
            q_op = ARHSAV3StartScoreGradQSegmentH2Sm100(num_threads=num_threads)
            run_arhsa_v3_start_score_backward_segmented.compile_cache[q_key] = cute.compile(
                q_op,
                to_cute_tensor(row_repr),
                to_cute_tensor(grad_out),
                to_cute_tensor(start_feature_rows, assumed_align=4),
                to_cute_tensor(start_level_begin, assumed_align=4),
                to_cute_tensor(start_level_end, assumed_align=4),
                to_cute_tensor(grad_q),
                Float32(scale),
                Int32(qlevel_tasks),
                current_stream,
                options="--enable-tvm-ffi",
            )
        run_arhsa_v3_start_score_backward_segmented.compile_cache[q_key](
            row_repr,
            grad_out,
            start_feature_rows,
            start_level_begin,
            start_level_end,
            grad_q,
            Float32(scale),
            Int32(qlevel_tasks),
            current_stream,
        )

    if grad_q_out is not None and grad_q_out.data_ptr() != grad_q.data_ptr():
        grad_q_out.copy_(grad_q.to(dtype=grad_q_out.dtype))
        grad_q = grad_q_out
    elif grad_q_out is None and grad_q.dtype != q_levels.dtype:
        grad_q = grad_q.to(dtype=q_levels.dtype)
    if grad_row_out is not None and grad_row_out.data_ptr() != grad_row.data_ptr():
        grad_row_out.copy_(grad_row.to(dtype=grad_row_out.dtype))
        grad_row = grad_row_out
    elif grad_row_out is None and grad_row.dtype != row_repr.dtype:
        grad_row = grad_row.to(dtype=row_repr.dtype)
    return grad_q, grad_row


def run_arhsa_v3_open_score_forward(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    open_key_by_level: torch.Tensor,
    continue_row_index: torch.Tensor,
    continue_levels: torch.Tensor,
    up_bias: torch.Tensor,
    out: torch.Tensor | None = None,
) -> torch.Tensor:
    """Run fused two-head ARHSAv3 open-gate score dot."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4 or row_repr.ndim != 3 or open_key_by_level.ndim != 3:
        raise ValueError("q_levels, row_repr, and open_key_by_level must be 4D/3D/3D tensors")
    if q_levels.shape[2:] != row_repr.shape[1:] or row_repr.shape[1:] != open_key_by_level.shape[1:]:
        raise ValueError("q_levels, row_repr, and open_key_by_level head dimensions must match")
    if int(row_repr.shape[1]) != 2:
        raise ValueError("run_arhsa_v3_open_score_forward currently requires exactly two heads")
    if continue_row_index.ndim != 2:
        raise ValueError("continue_row_index must have shape [n_queries, n_groups]")
    if continue_levels.shape != (continue_row_index.shape[1],):
        raise ValueError(f"continue_levels shape mismatch: got {tuple(continue_levels.shape)}")
    if continue_row_index.shape[0] != q_levels.shape[0]:
        raise ValueError("continue_row_index query dimension must match q_levels")
    if up_bias.reshape(-1).numel() not in {1, 2}:
        raise ValueError("up_bias must be scalar or length two")
    for tensor_name, tensor in (
        ("q_levels", q_levels),
        ("row_repr", row_repr),
        ("open_key_by_level", open_key_by_level),
    ):
        if tensor.dtype not in _CUTE_BACKWARD_DTYPES:
            raise ValueError(f"{tensor_name} dtype must be one of {_CUTE_BACKWARD_DTYPES}")
    if out is None:
        out = torch.empty(
            (q_levels.shape[0], continue_row_index.shape[1], row_repr.shape[1]),
            dtype=row_repr.dtype,
            device=row_repr.device,
        )
    if out.shape != (q_levels.shape[0], continue_row_index.shape[1], row_repr.shape[1]):
        raise ValueError(f"out shape mismatch: got {tuple(out.shape)}")

    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    open_key_by_level = open_key_by_level.contiguous()
    continue_row_index = continue_row_index.to(device=q_levels.device, dtype=torch.int32).contiguous()
    continue_levels = continue_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    up_bias = up_bias.reshape(-1).to(device=q_levels.device).contiguous()
    out = out.contiguous()
    total_tasks = int(continue_row_index.numel())
    if total_tasks == 0:
        return out

    num_threads = int(os.environ.get("HSA_CUTE_V3_OPEN_SCORE_THREADS", "128"))
    if num_threads not in {128, 256, 512}:
        raise ValueError("HSA_CUTE_V3_OPEN_SCORE_THREADS must be 128, 256, or 512")
    scale = float(q_levels.shape[-1] ** 0.5)
    compile_key = (
        "arhsa_v3_open_score_h2",
        q_levels.dtype,
        row_repr.dtype,
        open_key_by_level.dtype,
        up_bias.dtype,
        out.dtype,
        q_levels.shape[2],
        q_levels.shape[3],
        continue_row_index.shape[1],
        up_bias.numel(),
        num_threads,
        torch.cuda.get_device_capability(q_levels.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_v3_open_score_forward.compile_cache:
        op = ARHSAV3OpenScoreH2Sm100(num_threads=num_threads)
        run_arhsa_v3_open_score_forward.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(q_levels),
            to_cute_tensor(row_repr),
            to_cute_tensor(open_key_by_level),
            to_cute_tensor(continue_row_index, assumed_align=4),
            to_cute_tensor(continue_levels, assumed_align=4),
            to_cute_tensor(up_bias),
            to_cute_tensor(out),
            Float32(scale),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_v3_open_score_forward.compile_cache[compile_key](
        q_levels,
        row_repr,
        open_key_by_level,
        continue_row_index,
        continue_levels,
        up_bias,
        out,
        Float32(scale),
        Int32(total_tasks),
        current_stream,
    )
    return out


def run_arhsa_v3_start_open_scores_forward(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    open_key_by_level: torch.Tensor,
    start_feature_rows: torch.Tensor,
    start_query_index: torch.Tensor,
    start_levels: torch.Tensor,
    continue_row_index: torch.Tensor,
    continue_levels: torch.Tensor,
    down_bias: torch.Tensor,
    up_bias: torch.Tensor,
    start_out: torch.Tensor | None = None,
    open_out: torch.Tensor | None = None,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Run packed ARHSAv3 start-score and open-score dots in one launch."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4 or row_repr.ndim != 3 or open_key_by_level.ndim != 3:
        raise ValueError("q_levels, row_repr, and open_key_by_level must be 4D/3D/3D tensors")
    if q_levels.shape[2:] != row_repr.shape[1:] or row_repr.shape[1:] != open_key_by_level.shape[1:]:
        raise ValueError("q_levels, row_repr, and open_key_by_level head dimensions must match")
    if int(row_repr.shape[1]) != 2:
        raise ValueError("run_arhsa_v3_start_open_scores_forward currently requires exactly two heads")
    if continue_row_index.ndim != 2:
        raise ValueError("continue_row_index must have shape [n_queries, n_groups]")
    if continue_row_index.shape[0] != q_levels.shape[0]:
        raise ValueError("continue_row_index query dimension must match q_levels")
    if continue_levels.shape != (continue_row_index.shape[1],):
        raise ValueError(f"continue_levels shape mismatch: got {tuple(continue_levels.shape)}")
    n_starts = int(start_feature_rows.numel())
    if start_query_index.shape != (n_starts,) or start_levels.shape != (n_starts,):
        raise ValueError("start_feature_rows, start_query_index, and start_levels must have matching 1D shapes")
    if down_bias.reshape(-1).numel() not in {1, 2}:
        raise ValueError("down_bias must be scalar or length two")
    if up_bias.reshape(-1).numel() not in {1, 2}:
        raise ValueError("up_bias must be scalar or length two")
    for tensor_name, tensor in (
        ("q_levels", q_levels),
        ("row_repr", row_repr),
        ("open_key_by_level", open_key_by_level),
    ):
        if tensor.dtype not in _CUTE_BACKWARD_DTYPES:
            raise ValueError(f"{tensor_name} dtype must be one of {_CUTE_BACKWARD_DTYPES}")

    if start_out is None:
        start_dtype = torch.promote_types(row_repr.dtype, down_bias.dtype)
        start_out = torch.empty(
            (n_starts, row_repr.shape[1]),
            dtype=start_dtype,
            device=row_repr.device,
        )
    if open_out is None:
        open_out = torch.empty(
            (q_levels.shape[0], continue_row_index.shape[1], row_repr.shape[1]),
            dtype=row_repr.dtype,
            device=row_repr.device,
        )
    if start_out.shape != (n_starts, row_repr.shape[1]):
        raise ValueError(f"start_out shape mismatch: got {tuple(start_out.shape)}")
    if open_out.shape != (q_levels.shape[0], continue_row_index.shape[1], row_repr.shape[1]):
        raise ValueError(f"open_out shape mismatch: got {tuple(open_out.shape)}")

    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    open_key_by_level = open_key_by_level.contiguous()
    start_feature_rows = start_feature_rows.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    start_query_index = start_query_index.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    start_levels = start_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    continue_row_index = continue_row_index.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    continue_levels = continue_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    down_bias = down_bias.reshape(-1).to(device=q_levels.device).contiguous()
    up_bias = up_bias.reshape(-1).to(device=q_levels.device).contiguous()
    start_out = start_out.contiguous()
    open_out = open_out.contiguous()

    start_tasks = int(start_feature_rows.numel())
    total_tasks = start_tasks + int(continue_row_index.numel())
    if total_tasks == 0:
        return start_out, open_out

    num_threads = int(os.environ.get("HSA_CUTE_V3_START_OPEN_SCORE_THREADS", "128"))
    if num_threads not in {128, 256, 512}:
        raise ValueError("HSA_CUTE_V3_START_OPEN_SCORE_THREADS must be 128, 256, or 512")
    scale = float(q_levels.shape[-1] ** 0.5)
    compile_key = (
        "arhsa_v3_start_open_scores_h2",
        q_levels.dtype,
        row_repr.dtype,
        open_key_by_level.dtype,
        down_bias.dtype,
        up_bias.dtype,
        start_out.dtype,
        open_out.dtype,
        q_levels.shape[2],
        q_levels.shape[3],
        continue_row_index.shape[1],
        down_bias.numel(),
        up_bias.numel(),
        num_threads,
        torch.cuda.get_device_capability(q_levels.device),
    )
    current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
    if compile_key not in run_arhsa_v3_start_open_scores_forward.compile_cache:
        op = ARHSAV3StartOpenScoresH2Sm100(num_threads=num_threads)
        run_arhsa_v3_start_open_scores_forward.compile_cache[compile_key] = cute.compile(
            op,
            to_cute_tensor(q_levels),
            to_cute_tensor(row_repr),
            to_cute_tensor(open_key_by_level),
            to_cute_tensor(start_feature_rows, assumed_align=4),
            to_cute_tensor(start_query_index, assumed_align=4),
            to_cute_tensor(start_levels, assumed_align=4),
            to_cute_tensor(continue_row_index, assumed_align=4),
            to_cute_tensor(continue_levels, assumed_align=4),
            to_cute_tensor(down_bias),
            to_cute_tensor(up_bias),
            to_cute_tensor(start_out),
            to_cute_tensor(open_out),
            Float32(scale),
            Int32(start_tasks),
            Int32(total_tasks),
            current_stream,
            options="--enable-tvm-ffi",
        )
    run_arhsa_v3_start_open_scores_forward.compile_cache[compile_key](
        q_levels,
        row_repr,
        open_key_by_level,
        start_feature_rows,
        start_query_index,
        start_levels,
        continue_row_index,
        continue_levels,
        down_bias,
        up_bias,
        start_out,
        open_out,
        Float32(scale),
        Int32(start_tasks),
        Int32(total_tasks),
        current_stream,
    )
    return start_out, open_out


def run_arhsa_v3_start_open_scores_backward(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    open_key_by_level: torch.Tensor,
    grad_start: torch.Tensor,
    grad_open: torch.Tensor,
    start_feature_rows: torch.Tensor,
    start_query_index: torch.Tensor,
    start_levels: torch.Tensor,
    continue_row_index: torch.Tensor,
    continue_levels: torch.Tensor,
    down_bias: torch.Tensor,
    up_bias: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Run packed ARHSAv3 start/open score backward in one launch."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4 or row_repr.ndim != 3 or open_key_by_level.ndim != 3:
        raise ValueError("q_levels, row_repr, and open_key_by_level must be 4D/3D/3D tensors")
    if q_levels.shape[2:] != row_repr.shape[1:] or row_repr.shape[1:] != open_key_by_level.shape[1:]:
        raise ValueError("q_levels, row_repr, and open_key_by_level head dimensions must match")
    if int(row_repr.shape[1]) != 2:
        raise ValueError("run_arhsa_v3_start_open_scores_backward currently requires exactly two heads")
    n_starts = int(start_feature_rows.numel())
    if grad_start.shape != (n_starts, row_repr.shape[1]):
        raise ValueError(f"grad_start shape mismatch: got {tuple(grad_start.shape)}")
    if continue_row_index.ndim != 2:
        raise ValueError("continue_row_index must have shape [n_queries, n_groups]")
    if continue_row_index.shape[0] != q_levels.shape[0]:
        raise ValueError("continue_row_index query dimension must match q_levels")
    if grad_open.shape != (q_levels.shape[0], continue_row_index.shape[1], row_repr.shape[1]):
        raise ValueError(f"grad_open shape mismatch: got {tuple(grad_open.shape)}")
    if start_query_index.shape != (n_starts,) or start_levels.shape != (n_starts,):
        raise ValueError("start_feature_rows, start_query_index, and start_levels must have matching 1D shapes")
    if continue_levels.shape != (continue_row_index.shape[1],):
        raise ValueError(f"continue_levels shape mismatch: got {tuple(continue_levels.shape)}")
    if down_bias.reshape(-1).numel() not in {1, 2}:
        raise ValueError("down_bias must be scalar or length two")
    if up_bias.reshape(-1).numel() not in {1, 2}:
        raise ValueError("up_bias must be scalar or length two")
    for tensor_name, tensor in (
        ("q_levels", q_levels),
        ("row_repr", row_repr),
        ("open_key_by_level", open_key_by_level),
        ("grad_start", grad_start),
        ("grad_open", grad_open),
    ):
        if tensor.dtype not in _CUTE_BACKWARD_DTYPES:
            raise ValueError(f"{tensor_name} dtype must be one of {_CUTE_BACKWARD_DTYPES}")

    grad_q_out_dtype = q_levels.dtype
    grad_row_out_dtype = row_repr.dtype
    grad_open_key_out_dtype = open_key_by_level.dtype
    grad_q = torch.zeros_like(q_levels, dtype=torch.float32)
    grad_row = torch.zeros_like(row_repr, dtype=torch.float32)
    grad_open_key = torch.zeros_like(open_key_by_level, dtype=torch.float32)
    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    open_key_by_level = open_key_by_level.contiguous()
    grad_start = grad_start.contiguous()
    grad_open = grad_open.contiguous()
    start_feature_rows = start_feature_rows.to(device=q_levels.device, dtype=torch.int32).contiguous()
    start_query_index = start_query_index.to(device=q_levels.device, dtype=torch.int32).contiguous()
    start_levels = start_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    continue_row_index = continue_row_index.to(device=q_levels.device, dtype=torch.int32).contiguous()
    continue_levels = continue_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    start_tasks = int(start_feature_rows.numel())
    total_tasks = start_tasks + int(continue_row_index.numel())
    use_vec_d64 = (
        os.environ.get("HSA_CUTE_V3_START_OPEN_SCORE_BWD_VEC", "1") != "0"
        and int(q_levels.shape[2]) == 2
        and int(q_levels.shape[3]) == 64
    )
    bias_sum_mode = os.environ.get("HSA_CUTE_V3_START_OPEN_SCORE_BWD_BIAS_SUM", "auto").lower()
    if bias_sum_mode in {"1", "true", "yes", "on"}:
        bias_sum_requested = True
    elif bias_sum_mode in {"0", "false", "no", "off"}:
        bias_sum_requested = False
    else:
        bias_sum_threshold = int(
            os.environ.get("HSA_CUTE_V3_START_OPEN_SCORE_BWD_BIAS_SUM_MIN_TASKS", "65536")
        )
        bias_sum_requested = total_tasks >= bias_sum_threshold
    bias_sum_outside = use_vec_d64 and bias_sum_requested
    cta_reduce_grad_q = (
        use_vec_d64
        and os.environ.get("HSA_CUTE_V3_START_OPEN_SCORE_BWD_CTA_REDUCE_Q", "0") != "0"
    )
    if bias_sum_outside:
        if down_bias.reshape(-1).numel() > 1:
            grad_down_bias = grad_start.sum(dim=0, dtype=torch.float32).contiguous()
        else:
            grad_down_bias = grad_start.sum(dtype=torch.float32).reshape(1)
        if up_bias.reshape(-1).numel() > 1:
            grad_up_bias = grad_open.sum(dim=(0, 1), dtype=torch.float32).contiguous()
        else:
            grad_up_bias = grad_open.sum(dtype=torch.float32).reshape(1)
    else:
        grad_down_bias = torch.zeros(
            down_bias.reshape(-1).numel(),
            device=q_levels.device,
            dtype=torch.float32,
        )
        grad_up_bias = torch.zeros(
            up_bias.reshape(-1).numel(),
            device=q_levels.device,
            dtype=torch.float32,
        )
    if total_tasks > 0:
        num_threads = int(os.environ.get("HSA_CUTE_V3_START_OPEN_SCORE_BWD_THREADS", "128"))
        if num_threads not in {128, 256, 512}:
            raise ValueError("HSA_CUTE_V3_START_OPEN_SCORE_BWD_THREADS must be 128, 256, or 512")
        scale = float(q_levels.shape[-1] ** 0.5)
        compile_key = (
            "arhsa_v3_start_open_scores_backward_h2_d64_vec"
            if use_vec_d64
            else "arhsa_v3_start_open_scores_backward_h2",
            q_levels.dtype,
            row_repr.dtype,
            open_key_by_level.dtype,
            grad_start.dtype,
            grad_open.dtype,
            grad_q.dtype,
            grad_row.dtype,
            grad_open_key.dtype,
            q_levels.shape[2],
            q_levels.shape[3],
            continue_row_index.shape[1],
            grad_down_bias.numel(),
            grad_up_bias.numel(),
            num_threads,
            bias_sum_outside,
            cta_reduce_grad_q,
            torch.cuda.get_device_capability(q_levels.device),
        )
        current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
        if compile_key not in run_arhsa_v3_start_open_scores_backward.compile_cache:
            if use_vec_d64:
                op = ARHSAV3StartOpenScoresBackwardH2D64VecSm100(
                    num_threads=num_threads,
                    accumulate_bias=not bias_sum_outside,
                    cta_reduce_grad_q=cta_reduce_grad_q,
                )
            else:
                op = ARHSAV3StartOpenScoresBackwardH2Sm100(num_threads=num_threads)
            run_arhsa_v3_start_open_scores_backward.compile_cache[compile_key] = cute.compile(
                op,
                to_cute_tensor(q_levels),
                to_cute_tensor(row_repr),
                to_cute_tensor(open_key_by_level),
                to_cute_tensor(grad_start),
                to_cute_tensor(grad_open),
                to_cute_tensor(start_feature_rows, assumed_align=4),
                to_cute_tensor(start_query_index, assumed_align=4),
                to_cute_tensor(start_levels, assumed_align=4),
                to_cute_tensor(continue_row_index, assumed_align=4),
                to_cute_tensor(continue_levels, assumed_align=4),
                to_cute_tensor(grad_q),
                to_cute_tensor(grad_row),
                to_cute_tensor(grad_open_key),
                to_cute_tensor(grad_down_bias),
                to_cute_tensor(grad_up_bias),
                Float32(scale),
                Int32(start_tasks),
                Int32(total_tasks),
                current_stream,
                options="--enable-tvm-ffi",
            )
        run_arhsa_v3_start_open_scores_backward.compile_cache[compile_key](
            q_levels,
            row_repr,
            open_key_by_level,
            grad_start,
            grad_open,
            start_feature_rows,
            start_query_index,
            start_levels,
            continue_row_index,
            continue_levels,
            grad_q,
            grad_row,
            grad_open_key,
            grad_down_bias,
            grad_up_bias,
            Float32(scale),
            Int32(start_tasks),
            Int32(total_tasks),
            current_stream,
        )

    if grad_q.dtype != grad_q_out_dtype:
        grad_q = grad_q.to(dtype=grad_q_out_dtype)
    if grad_row.dtype != grad_row_out_dtype:
        grad_row = grad_row.to(dtype=grad_row_out_dtype)
    if grad_open_key.dtype != grad_open_key_out_dtype:
        grad_open_key = grad_open_key.to(dtype=grad_open_key_out_dtype)
    return (
        grad_q,
        grad_row,
        grad_open_key,
        grad_down_bias.to(dtype=down_bias.dtype).reshape_as(down_bias),
        grad_up_bias.to(dtype=up_bias.dtype).reshape_as(up_bias),
    )


def run_arhsa_v3_start_open_self_mass_backward(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    open_key_by_level: torch.Tensor,
    grad_start: torch.Tensor,
    grad_open: torch.Tensor,
    self_mass: torch.Tensor,
    grad_self_mass: torch.Tensor,
    start_feature_rows: torch.Tensor,
    start_query_index: torch.Tensor,
    start_levels: torch.Tensor,
    continue_row_index: torch.Tensor,
    continue_levels: torch.Tensor,
    initial_up_feature_rows: torch.Tensor,
    initial_up_is_closed: torch.Tensor,
    down_bias: torch.Tensor,
    up_bias: torch.Tensor,
    leaf_level: int,
    parent_level: int,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Combined backward for packed start/open score dots and self-mass."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4 or row_repr.ndim != 3 or open_key_by_level.ndim != 3:
        raise ValueError("q_levels, row_repr, and open_key_by_level must be 4D/3D/3D tensors")
    if q_levels.shape[2:] != row_repr.shape[1:] or row_repr.shape[1:] != open_key_by_level.shape[1:]:
        raise ValueError("q_levels, row_repr, and open_key_by_level head dimensions must match")
    if int(q_levels.shape[2]) != 2 or int(q_levels.shape[3]) != 64:
        raise ValueError("run_arhsa_v3_start_open_self_mass_backward requires two heads and head_dim=64")
    n_queries = int(q_levels.shape[0])
    n_starts = int(start_feature_rows.numel())
    if grad_start.shape != (n_starts, row_repr.shape[1]):
        raise ValueError(f"grad_start shape mismatch: got {tuple(grad_start.shape)}")
    if continue_row_index.ndim != 2 or continue_row_index.shape[0] != n_queries:
        raise ValueError("continue_row_index must have shape [n_queries, n_groups]")
    if continue_levels.shape != (continue_row_index.shape[1],):
        raise ValueError(f"continue_levels shape mismatch: got {tuple(continue_levels.shape)}")
    if grad_open.shape != (n_queries, continue_row_index.shape[1], row_repr.shape[1]):
        raise ValueError(f"grad_open shape mismatch: got {tuple(grad_open.shape)}")
    if self_mass.shape != (n_queries, row_repr.shape[1]):
        raise ValueError(f"self_mass shape mismatch: got {tuple(self_mass.shape)}")
    if grad_self_mass.shape != self_mass.shape:
        raise ValueError(f"grad_self_mass shape mismatch: got {tuple(grad_self_mass.shape)}")
    if initial_up_feature_rows.shape != (n_queries,):
        raise ValueError(f"initial_up_feature_rows shape mismatch: got {tuple(initial_up_feature_rows.shape)}")
    if initial_up_is_closed.shape != (n_queries,):
        raise ValueError(f"initial_up_is_closed shape mismatch: got {tuple(initial_up_is_closed.shape)}")
    if start_query_index.shape != (n_starts,) or start_levels.shape != (n_starts,):
        raise ValueError("start_feature_rows, start_query_index, and start_levels must have matching 1D shapes")
    if down_bias.reshape(-1).numel() not in {1, 2}:
        raise ValueError("down_bias must be scalar or length two")
    if up_bias.reshape(-1).numel() not in {1, 2}:
        raise ValueError("up_bias must be scalar or length two")
    for tensor_name, tensor in (
        ("q_levels", q_levels),
        ("row_repr", row_repr),
        ("open_key_by_level", open_key_by_level),
        ("grad_start", grad_start),
        ("grad_open", grad_open),
        ("self_mass", self_mass),
        ("grad_self_mass", grad_self_mass),
    ):
        if tensor.dtype not in _CUTE_BACKWARD_DTYPES:
            raise ValueError(f"{tensor_name} dtype must be one of {_CUTE_BACKWARD_DTYPES}")

    grad_q_out_dtype = q_levels.dtype
    grad_row_out_dtype = row_repr.dtype
    grad_open_key_out_dtype = open_key_by_level.dtype
    grad_q = torch.zeros_like(q_levels, dtype=torch.float32)
    grad_row = torch.zeros_like(row_repr, dtype=torch.float32)
    grad_open_key = torch.zeros_like(open_key_by_level, dtype=torch.float32)
    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    open_key_by_level = open_key_by_level.contiguous()
    grad_start = grad_start.contiguous()
    grad_open = grad_open.contiguous()
    self_mass = self_mass.contiguous()
    grad_self_mass = grad_self_mass.contiguous()
    start_feature_rows = start_feature_rows.to(device=q_levels.device, dtype=torch.int32).contiguous()
    start_query_index = start_query_index.to(device=q_levels.device, dtype=torch.int32).contiguous()
    start_levels = start_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    continue_row_index = continue_row_index.to(device=q_levels.device, dtype=torch.int32).contiguous()
    continue_levels = continue_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    initial_up_feature_rows = initial_up_feature_rows.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    initial_up_is_closed = initial_up_is_closed.to(
        device=q_levels.device,
        dtype=torch.int32,
    ).contiguous()
    start_open_tasks = n_starts + int(continue_row_index.numel())
    total_tasks = start_open_tasks + n_queries
    bias_sum_mode = os.environ.get(
        "HSA_CUTE_V3_START_OPEN_SCORE_BWD_BIAS_SUM",
        "auto",
    ).lower()
    if bias_sum_mode in {"1", "true", "yes", "on"}:
        bias_sum_requested = True
    elif bias_sum_mode in {"0", "false", "no", "off"}:
        bias_sum_requested = False
    else:
        bias_sum_threshold = int(
            os.environ.get("HSA_CUTE_V3_START_OPEN_SCORE_BWD_BIAS_SUM_MIN_TASKS", "65536")
        )
        bias_sum_requested = start_open_tasks >= bias_sum_threshold
    bias_sum_outside = bias_sum_requested
    if bias_sum_outside:
        if down_bias.reshape(-1).numel() > 1:
            grad_down_bias = grad_start.sum(dim=0, dtype=torch.float32).contiguous()
        else:
            grad_down_bias = grad_start.sum(dtype=torch.float32).reshape(1)
        if up_bias.reshape(-1).numel() > 1:
            grad_up_bias = grad_open.sum(dim=(0, 1), dtype=torch.float32).contiguous()
        else:
            grad_up_bias = grad_open.sum(dtype=torch.float32).reshape(1)
    else:
        grad_down_bias = torch.zeros(
            down_bias.reshape(-1).numel(),
            device=q_levels.device,
            dtype=torch.float32,
        )
        grad_up_bias = torch.zeros(
            up_bias.reshape(-1).numel(),
            device=q_levels.device,
            dtype=torch.float32,
        )
    if total_tasks > 0:
        num_threads = int(os.environ.get("HSA_CUTE_V3_START_OPEN_SELF_MASS_BWD_THREADS", "128"))
        if num_threads not in {128, 256, 512}:
            raise ValueError("HSA_CUTE_V3_START_OPEN_SELF_MASS_BWD_THREADS must be 128, 256, or 512")
        cta_reduce_grad_q = (
            os.environ.get("HSA_CUTE_V3_START_OPEN_SELF_MASS_BWD_CTA_REDUCE_Q", "0") != "0"
        )
        scale = float(q_levels.shape[-1] ** 0.5)
        compile_key = (
            "arhsa_v3_start_open_self_mass_backward_h2_d64_vec",
            q_levels.dtype,
            row_repr.dtype,
            open_key_by_level.dtype,
            grad_start.dtype,
            grad_open.dtype,
            self_mass.dtype,
            grad_self_mass.dtype,
            grad_q.dtype,
            grad_row.dtype,
            grad_open_key.dtype,
            q_levels.shape[2],
            q_levels.shape[3],
            continue_row_index.shape[1],
            grad_down_bias.numel(),
            grad_up_bias.numel(),
            int(leaf_level),
            int(parent_level),
            num_threads,
            bias_sum_outside,
            cta_reduce_grad_q,
            torch.cuda.get_device_capability(q_levels.device),
        )
        current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
        if compile_key not in run_arhsa_v3_start_open_self_mass_backward.compile_cache:
            op = ARHSAV3StartOpenSelfMassBackwardH2D64VecSm100(
                num_threads=num_threads,
                accumulate_start_open_bias=not bias_sum_outside,
                cta_reduce_grad_q=cta_reduce_grad_q,
            )
            run_arhsa_v3_start_open_self_mass_backward.compile_cache[compile_key] = cute.compile(
                op,
                to_cute_tensor(q_levels),
                to_cute_tensor(row_repr),
                to_cute_tensor(open_key_by_level),
                to_cute_tensor(grad_start),
                to_cute_tensor(grad_open),
                to_cute_tensor(self_mass),
                to_cute_tensor(grad_self_mass),
                to_cute_tensor(start_feature_rows, assumed_align=4),
                to_cute_tensor(start_query_index, assumed_align=4),
                to_cute_tensor(start_levels, assumed_align=4),
                to_cute_tensor(continue_row_index, assumed_align=4),
                to_cute_tensor(continue_levels, assumed_align=4),
                to_cute_tensor(initial_up_feature_rows, assumed_align=4),
                to_cute_tensor(initial_up_is_closed, assumed_align=4),
                to_cute_tensor(grad_q),
                to_cute_tensor(grad_row),
                to_cute_tensor(grad_open_key),
                to_cute_tensor(grad_down_bias),
                to_cute_tensor(grad_up_bias),
                Float32(scale),
                Int32(n_starts),
                Int32(start_open_tasks),
                Int32(total_tasks),
                Int32(int(leaf_level)),
                Int32(int(parent_level)),
                current_stream,
                options="--enable-tvm-ffi",
            )
        run_arhsa_v3_start_open_self_mass_backward.compile_cache[compile_key](
            q_levels,
            row_repr,
            open_key_by_level,
            grad_start,
            grad_open,
            self_mass,
            grad_self_mass,
            start_feature_rows,
            start_query_index,
            start_levels,
            continue_row_index,
            continue_levels,
            initial_up_feature_rows,
            initial_up_is_closed,
            grad_q,
            grad_row,
            grad_open_key,
            grad_down_bias,
            grad_up_bias,
            Float32(scale),
            Int32(n_starts),
            Int32(start_open_tasks),
            Int32(total_tasks),
            Int32(int(leaf_level)),
            Int32(int(parent_level)),
            current_stream,
        )

    if grad_q.dtype != grad_q_out_dtype:
        grad_q = grad_q.to(dtype=grad_q_out_dtype)
    if grad_row.dtype != grad_row_out_dtype:
        grad_row = grad_row.to(dtype=grad_row_out_dtype)
    if grad_open_key.dtype != grad_open_key_out_dtype:
        grad_open_key = grad_open_key.to(dtype=grad_open_key_out_dtype)
    return (
        grad_q,
        grad_row,
        grad_open_key,
        grad_down_bias.to(dtype=down_bias.dtype).reshape_as(down_bias),
        grad_up_bias.to(dtype=up_bias.dtype).reshape_as(up_bias),
    )


def run_arhsa_v3_open_score_backward(
    q_levels: torch.Tensor,
    row_repr: torch.Tensor,
    open_key_by_level: torch.Tensor,
    grad_out: torch.Tensor,
    continue_row_index: torch.Tensor,
    continue_levels: torch.Tensor,
    up_bias: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
    """Backward for fused two-head ARHSAv3 open-gate score dot."""
    _require_cute_runtime()
    if q_levels.device.type != "cuda":
        raise ValueError("q_levels must be a CUDA tensor")
    if q_levels.ndim != 4 or row_repr.ndim != 3 or open_key_by_level.ndim != 3:
        raise ValueError("q_levels, row_repr, and open_key_by_level must be 4D/3D/3D tensors")
    if int(row_repr.shape[1]) != 2:
        raise ValueError("run_arhsa_v3_open_score_backward currently requires exactly two heads")
    if grad_out.shape != (q_levels.shape[0], continue_row_index.shape[1], row_repr.shape[1]):
        raise ValueError(f"grad_out shape mismatch: got {tuple(grad_out.shape)}")
    for tensor_name, tensor in (
        ("q_levels", q_levels),
        ("row_repr", row_repr),
        ("open_key_by_level", open_key_by_level),
        ("grad_out", grad_out),
    ):
        if tensor.dtype not in _CUTE_BACKWARD_DTYPES:
            raise ValueError(f"{tensor_name} dtype must be one of {_CUTE_BACKWARD_DTYPES}")

    grad_q_out_dtype = q_levels.dtype
    grad_row_out_dtype = row_repr.dtype
    grad_open_key_out_dtype = open_key_by_level.dtype
    grad_q = (
        torch.zeros_like(q_levels)
        if q_levels.dtype == torch.float32
        else torch.zeros_like(q_levels, dtype=torch.float32)
    )
    grad_row = (
        torch.zeros_like(row_repr)
        if row_repr.dtype == torch.float32
        else torch.zeros_like(row_repr, dtype=torch.float32)
    )
    grad_open_key = (
        torch.zeros_like(open_key_by_level)
        if open_key_by_level.dtype == torch.float32
        else torch.zeros_like(open_key_by_level, dtype=torch.float32)
    )
    grad_up_bias = torch.zeros(
        up_bias.reshape(-1).numel(),
        device=q_levels.device,
        dtype=torch.float32,
    )

    q_levels = q_levels.contiguous()
    row_repr = row_repr.contiguous()
    open_key_by_level = open_key_by_level.contiguous()
    grad_out = grad_out.contiguous()
    continue_row_index = continue_row_index.to(device=q_levels.device, dtype=torch.int32).contiguous()
    continue_levels = continue_levels.to(device=q_levels.device, dtype=torch.int32).contiguous()
    total_tasks = int(continue_row_index.numel())
    if total_tasks > 0:
        num_threads = int(os.environ.get("HSA_CUTE_V3_OPEN_SCORE_THREADS", "128"))
        if num_threads not in {128, 256, 512}:
            raise ValueError("HSA_CUTE_V3_OPEN_SCORE_THREADS must be 128, 256, or 512")
        scale = float(q_levels.shape[-1] ** 0.5)
        compile_key = (
            "arhsa_v3_open_score_backward_h2",
            q_levels.dtype,
            row_repr.dtype,
            open_key_by_level.dtype,
            grad_out.dtype,
            grad_q.dtype,
            grad_row.dtype,
            grad_open_key.dtype,
            grad_up_bias.dtype,
            q_levels.shape[2],
            q_levels.shape[3],
            continue_row_index.shape[1],
            grad_up_bias.numel(),
            num_threads,
            torch.cuda.get_device_capability(q_levels.device),
        )
        current_stream = cuda.CUstream(torch.cuda.current_stream().cuda_stream)
        if compile_key not in run_arhsa_v3_open_score_backward.compile_cache:
            op = ARHSAV3OpenScoreBackwardH2Sm100(num_threads=num_threads)
            run_arhsa_v3_open_score_backward.compile_cache[compile_key] = cute.compile(
                op,
                to_cute_tensor(q_levels),
                to_cute_tensor(row_repr),
                to_cute_tensor(open_key_by_level),
                to_cute_tensor(grad_out),
                to_cute_tensor(continue_row_index, assumed_align=4),
                to_cute_tensor(continue_levels, assumed_align=4),
                to_cute_tensor(grad_q),
                to_cute_tensor(grad_row),
                to_cute_tensor(grad_open_key),
                to_cute_tensor(grad_up_bias),
                Float32(scale),
                Int32(total_tasks),
                current_stream,
                options="--enable-tvm-ffi",
            )
        run_arhsa_v3_open_score_backward.compile_cache[compile_key](
            q_levels,
            row_repr,
            open_key_by_level,
            grad_out,
            continue_row_index,
            continue_levels,
            grad_q,
            grad_row,
            grad_open_key,
            grad_up_bias,
            Float32(scale),
            Int32(total_tasks),
            current_stream,
        )

    if grad_q.dtype != grad_q_out_dtype:
        grad_q = grad_q.to(dtype=grad_q_out_dtype)
    if grad_row.dtype != grad_row_out_dtype:
        grad_row = grad_row.to(dtype=grad_row_out_dtype)
    if grad_open_key.dtype != grad_open_key_out_dtype:
        grad_open_key = grad_open_key.to(dtype=grad_open_key_out_dtype)
    return grad_q, grad_row, grad_open_key, grad_up_bias.to(dtype=up_bias.dtype).reshape_as(up_bias)


