    if x_hat.shape != grad_y.shape:
        raise ValueError(f"x_hat shape mismatch: got {tuple(x_hat.shape)}")
    if rstd.shape != (grad_y.shape[0], 1):
        raise ValueError(f"rstd shape mismatch: got {tuple(rstd.shape)}")
